window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[36]={"id":"036","numero":36,"titre":"Contraception","objectifs":[{"id":"36-1","rang":"A","rubrique":"Définition","titre":"Connaître les différentes modalités de contraceptions existantes","contenu":"<p>La <span class=\"kw-def\">contraception</span> est l'ensemble des méthodes destinées <span class=\"kw-ci\">à éviter</span>, de façon <strong>réversible</strong> et pour une période donnée, la survenue d'une <span class=\"kw-ci\">grossesse</span>. Elle s'oppose à la <span class=\"kw-def\">stérilisation</span>, méthode <strong>définitive</strong>. L'indication principale est la maîtrise de la fertilité de façon <em>efficace, acceptable et non nuisible à la santé</em>.</p>\n\n      <p>On distingue <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes familles, à connaître pour le raisonnement EDN :</p>\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Méthodes</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hormonales non définitives</strong></td>\n            <td>\n              <strong>Combinées</strong> (œstrogène + progestatif) — <span class=\"kw-def\">COP</span> ; pilule, patch, anneau vaginal<br>\n              <strong>Progestatives seules</strong> — pilule microprogestative, implant SC, DIU au lévonorgestrel\n            </td>\n            <td>COP combinée = <span class=\"kw-alerte\">1ʳᵉ intention</span> chez la femme jeune sans <span class=\"kw-etio\">FRCV</span></td>\n          </tr>\n          <tr>\n            <td><strong>Non hormonales non définitives</strong></td>\n            <td>\n              <strong>DIU au cuivre</strong> (très efficace)<br>\n              <strong>Méthodes barrières</strong> : préservatif M/F, spermicide, diaphragme, cape cervicale<br>\n              <strong>Méthodes naturelles</strong> : Ogino-Knauss, températures, Billings, symptothermie\n            </td>\n            <td><span class=\"kw-alerte\">Méthodes naturelles non suffisamment efficaces</span> chez les femmes normalement fertiles</td>\n          </tr>\n          <tr>\n            <td><strong>Définitives (stérilisation)</strong></td>\n            <td>\n              <strong>Femme</strong> : <span class=\"kw-ttt\">ligature tubaire</span> (<span class=\"kw-ttt\">cœlioscopie</span>)<br>\n              <strong>Homme</strong> : <span class=\"kw-ttt\">vasectomie bilatérale</span>\n            </td>\n            <td>Encadrées par texte juridique : majeur·e + délai de réflexion <span class=\"kw-chiffre\">4 mois</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Bénéfices au-delà de la contraception</strong> : seul le <span class=\"kw-clinique\">préservatif</span> protège des <span class=\"kw-def\">IST</span>. Les contraceptions hormonales peuvent être prescrites pour des pathologies fonctionnelles/organiques gynécologiques et mammaires ou pour induire une <strong>aménorrhée thérapeutique</strong> (ex : hémorragie par troubles de l'hémostase, <span class=\"kw-etio\">endométriose</span>).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Malgré le large choix, <em>la contraception idéale n'existe pas</em>. Toujours laisser le choix à la femme après information complète et élimination des <span class=\"kw-ci\">contre-indications</span> — c'est la condition d'une bonne observance.\n      </div>","frequence":1},{"id":"36-2","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de contraceptions hormonales estro-progestatives, leur voie d’administration et leur classification","contenu":"<p>La <span class=\"kw-def\">contraception œstroprogestative</span> (COP) associe un <strong>œstrogène</strong> et un <strong>progestatif</strong>, administrés conjointement à doses variables. Elle existe sous 3 voies d'administration et plusieurs classes selon la nature du progestatif.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Composants</h4>\n      <table >\n        <thead><tr><th>Composant</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Œstrogène</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Éthinyl-œstradiol (EE)</span> — synthétique, dose <span class=\"kw-chiffre\">15 à 50 µg</span><br>\n              <span class=\"kw-ttt\">17β-œstradiol</span> ou <span class=\"kw-ttt\">valérate d'œstradiol</span> — dérivés naturels\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Progestatif</strong> (générations)</td>\n            <td>\n              <strong>1ʳᵉ génération</strong> : noréthistérone, lynestrénol — <em>non disponibles depuis 2016</em><br>\n              <strong>2ᵉ génération</strong> : <span class=\"kw-ttt\">lévonorgestrel</span>, <span class=\"kw-ttt\">norgestrel</span><br>\n              <strong>3ᵉ génération</strong> : gestodène, désogestrel, <span class=\"kw-ttt\">norgestimate</span><br>\n              <strong>4ᵉ génération</strong> : <span class=\"kw-ttt\">drospirénone</span> — <span class=\"kw-alerte\">non recommandée en 1ʳᵉ intention</span> (surrisque MTEV)<br>\n              <strong>Autres</strong> : acétate de cyprotérone, diénogest, acétate de nomégestrol, acétate de chlormadinone\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> selon la séquence d'administration</h4>\n      <ul>\n        <li><strong>Monophasique</strong> — dose des 2 composés <strong>fixe</strong> tout au long du cycle.</li>\n        <li><strong>Biphasique</strong> — 2 séquences de dosages (posologie plus forte en 2ᵈᵉ partie de <span class=\"kw-bio\">plaquette</span>).</li>\n        <li><strong>Triphasique</strong> — 3 phases de dosages.</li>\n        <li><strong>Quadriphasique</strong> — ex : <span class=\"kw-ttt\">Qlaira®</span> (valérate d'œstradiol).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Voies d'administration</h4>\n      <table >\n        <thead><tr><th>Voie</th><th>Forme</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Orale</strong></td><td>Pilule</td><td>Prise quotidienne à heure fixe, <span class=\"kw-bio\">plaquette</span> 21 cp + 7j arrêt, ou continue (21+7 placebo, ou 24+<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> min</span>idosée, ou 26+2 valérate)</td></tr>\n          <tr><td><strong>Transdermique</strong></td><td>Patch (<span class=\"kw-ttt\">Evra®</span>)</td><td><span class=\"kw-chiffre\">1 patch/semaine</span> ×<span class=\"kw-chiffre\"> 3 semaines</span>/4 — meilleure observance</td></tr>\n          <tr><td><strong>Vaginale</strong></td><td>Anneau (<span class=\"kw-ttt\">Nuvaring®</span>, <span class=\"kw-ttt\">Etonring®</span>)</td><td><span class=\"kw-chiffre\">3 semaines</span> en place +<span class=\"kw-chiffre\"> 1 semaine</span> d'interruption — meilleure observance</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Patch et anneau ont les <strong>mêmes <span class=\"kw-ci\">contre-indications</span> et effets indésirables</strong> que la voie orale (risque MTEV en particulier — équivalent à une COP de 3ᵉ génération).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">COP de 1ʳᵉ intention</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">COP de 2ᵉ génération par voie orale</span> (<span class=\"kw-alerte\">moins de risque MTEV</span> que les autres générations et voies).</li>\n        <li><span class=\"kw-ttt\">COP de 3ᵉ génération contenant du norgestimate</span> — possible en 1ʳᵉ intention (risque MTEV équivalent au lévonorgestrel).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span> · 224 — <span class=\"kw-def\">HTA</span> · 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":0},{"id":"36-3","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","contenu":"<p>La <span class=\"kw-def\">contraception progestative seule</span> repose sur des <strong>petites doses</strong> de progestatif (microprogestatifs) délivrées en continu. Elle se décline en 3 voies d'administration. À distinguer des <em>macroprogestatifs</em> à forte dose (rang C, hors AMM contraceptive).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Microprogestatifs disponibles en France</h4>\n      <table >\n        <thead><tr><th>Voie</th><th>DCI</th><th>Marque</th><th>Dose</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"3\"><strong>Orale</strong></td><td><span class=\"kw-ttt\">Lévonorgestrel</span></td><td>Microval®</td><td><span class=\"kw-chiffre\">0,030 mg/cp</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Désogestrel</span></td><td>Cérazette®, Antigone®, Desopop®, Optimizette®</td><td><span class=\"kw-chiffre\">0,075 mg/cp</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Drospirénone</span></td><td>Slinda®</td><td><span class=\"kw-chiffre\">4 mg/cp</span> (24 actifs + 4 placebo)</td></tr>\n          <tr><td><strong>Sous-cutanée (implant)</strong></td><td><span class=\"kw-ttt\">Étonogestrel</span></td><td>Nexplanon®</td><td><span class=\"kw-chiffre\">25-70 µg/24h</span> — durée <span class=\"kw-chiffre\">3 ans</span></td></tr>\n          <tr><td rowspan=\"3\"><strong>Intra-utérine (DIU)</strong></td><td rowspan=\"3\"><span class=\"kw-ttt\">Lévonorgestrel</span></td><td>Mirena® (<span class=\"kw-chiffre\">52 mg</span>)</td><td><span class=\"kw-chiffre\">20 µg/24h</span> — efficace <span class=\"kw-chiffre\">5 ans</span></td></tr>\n          <tr><td>Kyleena® (<span class=\"kw-chiffre\">19,5 mg</span>)</td><td><span class=\"kw-chiffre\">9 µg/24h</span> — efficace <span class=\"kw-chiffre\">5 ans</span></td></tr>\n          <tr><td>Jaydess® (<span class=\"kw-chiffre\">13,5 mg</span>)</td><td><span class=\"kw-chiffre\">6 µg/24h</span> — efficace <span class=\"kw-chiffre\">3 ans</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Particularités par voie</h4>\n      <ul>\n        <li><strong>Voie orale</strong> — prise à heure <span class=\"kw-alerte\">strictement fixe</span> ; retard maximum autorisé : <span class=\"kw-chiffre\">3h</span> (lévonorgestrel), <span class=\"kw-chiffre\">12h</span> (désogestrel), <span class=\"kw-chiffre\">24h</span> (drospirénone). Au-delà : <span class=\"kw-clinique\">contraception mécanique</span> indispensable <span class=\"kw-chiffre\">≥ 1 semaine</span>.</li>\n        <li><strong>Implant SC</strong> — pose à la face interne du bras non dominant après anesthésie locale ; <span class=\"kw-alerte\">observance parfaite</span> pendant <span class=\"kw-chiffre\">3 ans</span>.</li>\n        <li><strong>DIU au lévonorgestrel</strong> — atrophie de l'endomètre + épaississement glaire + toxicité spz ; <strong>spécialement indiqué</strong> en cas de <span class=\"kw-clinique\">dysménorrhée</span>, <span class=\"kw-clinique\">ménorragies fonctionnelles</span>, <span class=\"kw-etio\">adénomyose</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Macroprogestatifs (rang C, hors AMM contraceptive)</h4>\n      <p><em>Pregnanes</em> (acétate de chlormadinone <span class=\"kw-ttt\">Lutéran®</span>, médrogestérone <span class=\"kw-ttt\">Colprone®</span>, acétate de cyprotérone <span class=\"kw-ttt\">Androcur®</span>) et <em>norpregnane</em> (acétate de nomégestrol <span class=\"kw-ttt\">Lutényl®</span>). Action centrale antigonadotrope, indiqués chez femmes <span class=\"kw-chiffre\">&gt; 40 ans</span> ou pathologies œstrogéno-dépendantes (mastopathie bénigne, <span class=\"kw-etio\">endométriose</span>, myome, hyperplasie endométriale).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">Surveillance</span> ANSM.</strong> Macroprogestatifs en utilisation prolongée → surveillance clinique + <span class=\"kw-imagerie\">IRM cérébrale</span> en raison d'un risque hypothétique de <span class=\"kw-alerte\">méningiome</span>. Risque faible en valeur absolue mais documenté.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 224 — <span class=\"kw-def\">HTA</span> · 33 — <span class=\"kw-ci\">Allaitement</span> maternel · 299 — Tumeur intracranienne</em></p>","frequence":0},{"id":"36-4","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de contraception d’urgence","contenu":"<p>La <span class=\"kw-def\">contraception d'urgence</span> (CU) est une méthode d'exception, utilisée après un rapport non protégé ou un échec de contraception (oubli de pilule, <span class=\"kw-alerte\">rupture</span> de préservatif). Trois options selon le délai depuis le rapport à risque.</p>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Délai d'efficacité</th><th>Mécanisme</th><th>Accès / particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Lévonorgestrel</span></strong><span class=\"kw-chiffre\"> 1,5 mg</span> en prise unique<br><em>(Norlevo®)</em></td>\n            <td><span class=\"kw-chiffre\">≤ 72h</span> (<span class=\"kw-chiffre\">3 jours</span>) — d'autant plus efficace que prise précoce</td>\n            <td>Interfère avec le pic de LH, <strong>inhibe l'ovulation</strong> uniquement si pris en phase préovulatoire ; diffère/inhibe la croissance folliculaire</td>\n            <td><strong>Vente libre</strong>, sans ordonnance ; <span class=\"kw-alerte\">gratuite pour mineures et majeures</span> ; pharmacie, planning familial, lycée — <strong>aucune CI</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Acétate d'ulipristal</span></strong><span class=\"kw-chiffre\"> 30 mg</span> en prise unique per os<br><em>(EllaOne®)</em></td>\n            <td><span class=\"kw-chiffre\">≤ 120h</span> (<span class=\"kw-chiffre\">5 jours</span>) — plus efficace que le lévonorgestrel</td>\n            <td>Modulateur sélectif des récepteurs progestérone ; inhibe la croissance folliculaire, retarde le pic LH et la <span class=\"kw-alerte\">rupture</span> folliculaire de <span class=\"kw-chiffre\">3-5 j</span> (même après le pic LH)</td>\n            <td>Pharmacie avec ou sans ordonnance, planning familial ; remboursé <span class=\"kw-chiffre\">65 %</span> si ordonnance — <strong>CI : <span class=\"kw-ci\">asthme sévère</span>, <span class=\"kw-ci\">insuffisance hépatique</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">DIU au cuivre</span></strong></td>\n            <td><span class=\"kw-chiffre\">≤ 120h</span> (<span class=\"kw-chiffre\">5 jours</span>)</td>\n            <td>Toxicité directe du cuivre sur les gamètes + action <span class=\"kw-etio\">inflammatoire</span> endométriale (endomètre impropre à la nidation)</td>\n            <td><strong>1ʳᵉ intention en termes d'efficacité</strong> + contraception à longue durée d'action — plus rarement mise en œuvre en pratique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les pilules de CU visent à <strong>inhiber/retarder l'ovulation</strong>. Elles ont <em>peu ou pas d'effet</em> sur l'endomètre et l'implantation → ce ne sont <span class=\"kw-alerte\">PAS des méthodes contragestives</span> (≠ avortement).\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le DIU au cuivre est <strong>le plus efficace</strong> mais sous-utilisé. Information sur la CU = levier essentiel pour réduire le nombre d'IVG.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 37 — IVG · 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine</em></p>","frequence":0},{"id":"36-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes d’action de la contraception estro-progestative, progestative, d’urgence et intra-utérine","contenu":"<p>Chaque famille contraceptive agit par des <strong>mécanismes distincts</strong>, à connaître pour comprendre les indications et les CI.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception œstroprogestative (COP)</h4>\n      <table >\n        <thead><tr><th>Composant</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Composé progestatif</strong></td>\n            <td>\n              <strong>Action antigonadotrope</strong> : inhibe le <span class=\"kw-bio\">pic de LH</span> → blocage de l'ovulation<br>\n              <strong><span class=\"kw-bio\">Modification de la glaire cervicale</span></strong> : moins abondante, épaisse, imperméable aux spz<br>\n              <strong>Atrophie/hypotrophie de l'endomètre</strong> : moins apte à la nidation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Composé œstrogénique</strong></td>\n            <td>\n              <strong>Action antigonadotrope</strong> : inhibe la sécrétion de <span class=\"kw-bio\">FSH</span> → blocage de la croissance folliculaire cyclique\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception progestative seule (microprogestatifs)</h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Modification de la glaire cervicale</span></strong> (mécanisme principal) — épaisse, impropre au passage des spz ; justifie l'<strong>utilisation continue</strong>.</li>\n        <li><strong>Atrophie de l'endomètre</strong> — possible, le rend inapte à la nidation.</li>\n        <li><strong>Diminution de la mobilité tubaire</strong> + diminution de la mobilité des spz.</li>\n        <li><strong>Discrète action antigonadotrope</strong> pour le <span class=\"kw-ttt\">désogestrel</span> et la <span class=\"kw-ttt\">drospirénone</span> — action anti-ovulatoire par écrêtement du pic LH, faible action sur FSH.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception d'<span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Lévonorgestrel</span></strong> — interférence avec le pic de LH, inhibition de l'ovulation uniquement si pris en phase <strong>préovulatoire</strong> ; diffère/inhibe la croissance folliculaire.</li>\n        <li><strong><span class=\"kw-ttt\">Acétate d'ulipristal</span></strong> — inhibition de la croissance folliculaire en 1ʳᵉ partie de cycle, retard/inhibition du pic LH, retard de la <span class=\"kw-alerte\">rupture</span> folliculaire de <span class=\"kw-chiffre\">3-5 j</span> (même après pic LH).</li>\n        <li><strong><span class=\"kw-ttt\">DIU au cuivre</span></strong> — effet <span class=\"kw-etio\">toxique</span> direct du cuivre sur les gamètes + action <span class=\"kw-etio\">inflammatoire</span> endométriale (impropre à la nidation).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception intra-utérine (DIU)</h4>\n      <table >\n        <thead><tr><th>Type de DIU</th><th>Mécanisme d'action</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>DIU au cuivre</strong></td>\n            <td>\n              <strong>Toxicité directe</strong> probable sur les spermatozoïdes<br>\n              <strong>Toxicité indirecte</strong> : réaction <span class=\"kw-etio\">inflammatoire</span> endométriale induite par la présence de cuivre\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU au lévonorgestrel</strong></td>\n            <td>\n              <strong>Action progestative locale puissante</strong> sur l'endomètre (effet antiprolifératif marqué) + glaire cervicale épaissie<br>\n              <strong>Effet <span class=\"kw-etio\">toxique</span> sur les spermatozoïdes</strong> : capacitation, survie et migration profondément altérées\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/36/retrocontroles-ovariens-1.png\" alt=\"Schéma des rétrocontrôles ovariens sur l'axe hypothalamo-hypophyso-ovarien (axe HHO)\" loading=\"lazy\">\n        <figcaption>Rétrocontrôles ovariens sur l'axe HHO — pédagogique (hors-référentiel strict EDN). Source : fiche source EDN item 36.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/36/retrocontroles-ovariens-2.png\" alt=\"Schéma complémentaire des rétrocontrôles ovariens et de la régulation du cycle\" loading=\"lazy\">\n        <figcaption>Régulation du cycle ovarien — schéma complémentaire. Source : fiche source EDN item 36.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 42 — Aménorrhée</em></p>","frequence":0},{"id":"36-6","rang":"A","rubrique":"Définition","titre":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","contenu":"<p>Les contraceptions <span class=\"kw-def\">barrières</span> et <span class=\"kw-def\">naturelles</span> sont des méthodes <strong>non hormonales</strong>, d'efficacité inférieure aux méthodes hormonales et au DIU. Le <strong>préservatif masculin</strong> reste cependant la seule méthode protégeant des <span class=\"kw-def\">IST</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Méthodes barrières</h4>\n      <table >\n        <thead><tr><th>Méthode</th><th>Principe</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Préservatif masculin</span></strong></td>\n            <td>Barrière mécanique latex/polyuréthane sur le pénis</td>\n            <td><span class=\"kw-alerte\">Seule méthode protégeant des IST</span> ; indice de Pearl : <span class=\"kw-chiffre\">15 %</span> usage courant, <span class=\"kw-chiffre\">2 %</span> usage parfait</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Préservatif féminin</span></strong></td>\n            <td>Gaine en polyuréthane insérée dans le vagin</td>\n            <td>Protège aussi des IST ; Pearl <span class=\"kw-chiffre\">21 %</span> courant, <span class=\"kw-chiffre\">5 %</span> parfait</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Spermicides</span></strong> (crèmes, ovules, éponges)</td>\n            <td>Inactivation chimique des spz</td>\n            <td>Faible efficacité seule (Pearl <span class=\"kw-chiffre\">29 % / 18 %</span>) ; à associer à une autre méthode</td>\n          </tr>\n          <tr>\n            <td><strong>Diaphragme</strong></td>\n            <td>Dôme en silicone obturant le col, associé à un spermicide</td>\n            <td>Pearl <span class=\"kw-chiffre\">16 % / 6 %</span> ; <strong>plus difficile à utiliser en post-partum</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Cape cervicale</strong></td>\n            <td>Petite cupule en silicone sur le col</td>\n            <td>Efficacité variable selon parité : <span class=\"kw-chiffre\">16-32 %</span> usage courant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Méthodes naturelles</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Méthode Ogino-Knauss</span></strong> — abstinence pendant la période fertile estimée du cycle.</li>\n        <li><strong>Courbes de températures</strong> — repérage de l'ovulation par décalage thermique.</li>\n        <li><strong><span class=\"kw-ttt\">Méthode Billings</span></strong> — observation de la glaire cervicale.</li>\n        <li><strong>Symptothermie</strong> — combinaison température + glaire.</li>\n        <li><strong>Retrait</strong> (coït interrompu) — Pearl <span class=\"kw-chiffre\">27 % / 4 %</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Les méthodes naturelles sont <span class=\"kw-alerte\">non suffisamment efficaces</span> chez les femmes normalement fertiles. À <span class=\"kw-ci\">ne jamais</span> proposer comme méthode unique chez une femme en âge de procréer souhaitant éviter une <span class=\"kw-ci\">grossesse</span>, hors situations particulières (MAMA pendant l'allaitement, cf obj-11).\n      </div>","frequence":0},{"id":"36-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les contre-indications de la contraception estroprogestative, progestative, intra-utérine","contenu":"<p>Les <span class=\"kw-def\">contre-indications</span> diffèrent selon la classe contraceptive. La <strong>COP</strong> est la plus contraignante (risques carcinologique, MTEV, artériel). Les progestatifs seuls et le DIU ont des CI plus restreintes — ils sont souvent l'alternative en cas de CI à la COP.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-ci\">Contre-indications</span> à la COP</h4>\n      <table >\n        <thead><tr><th>Domaine</th><th>Contre-indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Carcinologique</strong></td>\n            <td>\n              <span class=\"kw-ci\">Tumeur maligne du sein</span> (même non hormonodépendante)<br>\n              <span class=\"kw-ci\">Tumeur maligne de l'utérus (endomètre)</span> — <em>même si la COP diminue le risque de cancer endomètre</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>MTEV</strong></td>\n            <td>\n              <span class=\"kw-ci\">ATCD personnel de MTEV</span><br>\n              <span class=\"kw-ci\">Thrombophilie</span> <span class=\"kw-etio\">génétique</span> ou acquise<br>\n              <span class=\"kw-ci\">MTEV idiopathique</span> avant <span class=\"kw-chiffre\">50 ans</span> chez un membre de la famille au <strong>1ᵉʳ degré</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque artériel — <span class=\"kw-ci\">CI absolues</span></strong></td>\n            <td>\n              <span class=\"kw-ci\">IDM</span>, <span class=\"kw-ci\">AVC ischémique</span>, <span class=\"kw-ci\">AOMI</span> — ATCD personnels ou familiaux 1ᵉʳ degré <span class=\"kw-chiffre\">&lt; 50 ans</span><br>\n              <span class=\"kw-ci\">Tabagisme important</span><br>\n              <span class=\"kw-ci\">HTA</span> (même traitée et équilibrée)<br>\n              <span class=\"kw-ci\">Migraine avec aura</span><br>\n              <span class=\"kw-ci\">DT1 compliqué</span> ou <span class=\"kw-def\">DT1</span> d'une durée <span class=\"kw-chiffre\">&gt; 20 ans</span><br>\n              <span class=\"kw-ci\">Dyslipidémie non équilibrée et/ou non traitée</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque artériel — <span class=\"kw-ci\">CI relatives</span></strong></td>\n            <td>\n              Âge <span class=\"kw-chiffre\">&gt; 35 ans</span>, <span class=\"kw-etio\">surpoids</span>, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">tabagisme</span><br>\n              <span class=\"kw-def\">DT2</span> (mais COP <span class=\"kw-ci\">à éviter</span>), <span class=\"kw-etio\">dyslipidémie</span> contrôlée, <span class=\"kw-def\">DT1</span> non compliqué <span class=\"kw-chiffre\">&lt; 20 ans</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pathologies hormonodépendantes</strong></td>\n            <td>\n              Vis-à-vis de la progestérone (ex : <span class=\"kw-alerte\">méningiome</span>)<br>\n              Vis-à-vis des œstrogènes (ex : <span class=\"kw-etio\">lupus évolutif</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <span class=\"kw-ci\">ATCD de lithiase biliaire</span><br>\n              <span class=\"kw-ci\">Connectivites</span>, <span class=\"kw-ci\">porphyries</span><br>\n              <span class=\"kw-ci\">Hémorragies génitales non diagnostiquées</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">CI relatives</span> autres</strong></td>\n            <td>\n              <span class=\"kw-etio\">Tabagisme</span> après <span class=\"kw-chiffre\">35 ans</span>, <span class=\"kw-def\">DT1</span> non compliqué, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">obésité</span><br>\n              Tumeurs bénignes du sein ou de l'utérus<br>\n              Hyperprolactinémie sans <span class=\"kw-def\">diagnostic étiologique</span> préalable<br>\n              <strong>Inducteurs enzymatiques</strong> (perte d'efficacité plutôt que CI)<br>\n              FA, <span class=\"kw-clinique\">arythmie</span>, coronaropathie, valvulopathie<br>\n              <span class=\"kw-etio\">Drépanocytose</span>, <span class=\"kw-etio\">MICI</span>, <span class=\"kw-etio\">SHU</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-ci\">Contre-indications</span> aux microprogestatifs (CI formelles)</h4>\n      <ul>\n        <li><span class=\"kw-ci\">Accidents thromboemboliques veineux <strong>évolutifs</strong></span></li>\n        <li><span class=\"kw-ci\">Pathologies hépatiques évolutives sévères</span></li>\n        <li><span class=\"kw-ci\">Cancer du sein</span> (y compris non hormonodépendants), <span class=\"kw-ci\">cancer de l'endomètre</span></li>\n        <li>Pathologies hormonodépendantes vis-à-vis de la progestérone (ex : <span class=\"kw-alerte\">méningiome</span>)</li>\n        <li><span class=\"kw-ci\">Saignements inexpliqués</span></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-ci\">Contre-indications</span> au DIU</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>CI</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tout DIU</strong></td>\n            <td>\n              <span class=\"kw-ci\">Grossesse en cours et désirée</span><br>\n              <span class=\"kw-ci\">Anomalies de la cavité utérine</span> (malformations, myomes utérins)<br>\n              <span class=\"kw-ci\">Valvulopathies à risque d'endocardite</span><br>\n              <span class=\"kw-ci\">Maladie trophoblastique gestationnelle maligne</span><br>\n              <span class=\"kw-ci\">Hémorragies génitales non diagnostiquées</span><br>\n              <strong>CI infectieuses</strong> : infection puerpérale en cours, ATCD infection génitale haute <span class=\"kw-chiffre\">&lt; 3 mois</span>, cervicite purulente, immédiatement après avortement septique, <span class=\"kw-def\">tuberculose</span> pelvienne avérée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU au cuivre</strong></td>\n            <td>\n              <span class=\"kw-ci\">Maladie de Wilson</span><br>\n              <span class=\"kw-ci\">Traitements immunosuppresseurs ou corticoïdes au long cours</span> <em>(DIU agit par inflammation, plus de bénéfice)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU hormonaux</strong></td>\n            <td>\n              <span class=\"kw-ci\">ATCD personnel de cancer du sein</span> (même non hormonodépendant)<br>\n              <span class=\"kw-ci\">ATCD personnel d'autres tumeurs hormonodépendantes</span> (méningiomes)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fréquent.</strong> Contrairement aux idées reçues, le <span class=\"kw-ttt\">DIU (cuivre ou hormonal)</span> n'est <strong>PAS un FdR de GEU</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span> · 224 — <span class=\"kw-def\">HTA</span> · 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face · 247 — <span class=\"kw-etio\">Diabète</span> · 312 — Tumeur sein · 300 — Tumeur col-corps utérin · 282 — <span class=\"kw-etio\">MICI</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 299 — Tumeur intracranienne</em></p>","frequence":2},{"id":"36-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les critères de choix en 1ère intention de la contraception estroprogestative","contenu":"<p>En l'<strong>absence de <span class=\"kw-def\">facteur de risque</span></strong>, le choix de 1ʳᵉ intention pour une COP est précis et a fait l'objet d'une recommandation HAS — il vise à minimiser le risque MTEV tout en garantissant l'efficacité.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Recommandation 1ʳᵉ intention.</strong> <span class=\"kw-ttt\">Pilule COP monophasique</span> associant un <span class=\"kw-ttt\">progestatif de 2ᵉ génération</span> (<span class=\"kw-ttt\">lévonorgestrel</span>) et de l'<span class=\"kw-ttt\">éthinyl-œstradiol &lt; 40 µg</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Alternative également acceptable en 1ʳᵉ intention</h4>\n      <p><span class=\"kw-ttt\">COP de 3ᵉ génération contenant du norgestimate</span> — risque MTEV équivalent au lévonorgestrel.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Situations nécessitant une adaptation</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Choix adapté</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge <span class=\"kw-chiffre\">&gt; 35-40 ans</span></strong></td>\n            <td>Préférer <span class=\"kw-ttt\">microprogestatif</span> ou <span class=\"kw-ttt\">DIU</span> ; éviter la COP si associée à d'autres <span class=\"kw-etio\">FRCV</span></td>\n          </tr>\n          <tr>\n            <td><strong>Femme à risque vasculaire</strong> (<span class=\"kw-etio\">FRCV</span> <span class=\"kw-chiffre\">≥ 1</span>)</td>\n            <td><span class=\"kw-ttt\">Contraception microprogestative</span> ou <span class=\"kw-ttt\">DIU au cuivre ou au lévonorgestrel</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Les progestatifs de <strong>3ᵉ et 4ᵉ générations</strong> (hors norgestimate), la <span class=\"kw-ttt\">drospirénone</span> et l'<span class=\"kw-ttt\">acétate de cyprotérone</span> sont <span class=\"kw-alerte\">les plus à risque MTEV</span> — à ne pas prescrire en 1ʳᵉ intention.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 247 — <span class=\"kw-etio\">Diabète</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 224 — <span class=\"kw-def\">HTA</span></em></p>","frequence":0},{"id":"36-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les éléments à explorer lors de l’entretien et de l’examen clinique avant la prescription d’une contraception hormonale et intra-utérine","contenu":"<p>L'évaluation pré-prescription vise à <strong>rechercher les CI</strong> (notamment vasculaires, carcinologiques, MTEV) et à identifier les éventuelles <strong>interactions médicamenteuses</strong>. L'examen clinique est ciblé.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire — recherche d'interactions médicamenteuses</h4>\n      <ul>\n        <li>Recherche de prise d'<strong>inducteurs enzymatiques</strong> (diminuent l'efficacité des COP) — mnémo <span class=\"kw-ttt\">PRECaMPaGNe</span> (Phénytoïne, Rifampicine, Éfavirenz/Carbamazépine, Modafinil, Phénobarbital, Griséofulvine, Névirapine).</li>\n        <li><strong>Cas particulier de la <span class=\"kw-ttt\">lamotrigine</span></strong> : les COP <strong>accélèrent</strong> son métabolisme → <span class=\"kw-alerte\">diminution de la concentration plasmatique</span> → <span class=\"kw-alerte\">recrudescence des crises d'épilepsie</span>. <span class=\"kw-def\">Surveillance</span> rapprochée si association.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen clinique</h4>\n      <ul>\n        <li>Recherche systématique de <strong><span class=\"kw-ci\">contre-indications</span></strong> (cf obj-6).</li>\n        <li><span class=\"kw-clinique\">Examen mammaire</span>.</li>\n        <li><span class=\"kw-clinique\">Pression artérielle</span> (PA).</li>\n        <li><span class=\"kw-clinique\">IMC</span> (poids, taille).</li>\n        <li><strong><span class=\"kw-clinique\">Examen gynécologique/pelvien</span> : <span class=\"kw-alerte\">non obligatoire</span></strong> — notamment chez les jeunes filles lors des 1ʳᵉˢ consultations.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan paraclinique avant instauration COP</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sans particularité</strong></td>\n            <td><span class=\"kw-alerte\">Aucun bilan paraclinique nécessaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Âge <span class=\"kw-chiffre\">≥ 25 ans</span></strong></td>\n            <td><span class=\"kw-imagerie\">Frottis cervico-vaginal</span> (FCV) — selon les recommandations, tous les <span class=\"kw-chiffre\">3 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux de <span class=\"kw-etio\">dyslipidémie</span> ou d'accidents artériels</strong></td>\n            <td><span class=\"kw-bio\">Bilan lipidique</span> + <span class=\"kw-bio\">glycémie à jeun</span></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD familiaux de MTEV au 1ᵉʳ degré</strong></td>\n            <td>\n              <strong>Bilan de thrombophilie</strong> :<br>\n              <span class=\"kw-bio\">TP, TCA</span> — détection d'un <span class=\"kw-ttt\">anticoagulant</span> circulant<br>\n              <span class=\"kw-bio\">Dosage AT, protéine C, protéine S</span><br>\n              <span class=\"kw-bio\">Test de résistance à la protéine C activée</span><br>\n              <span class=\"kw-bio\">Recherche mutation FV (Leiden)</span>, <span class=\"kw-bio\">mutation FII (prothrombine)</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 224 — <span class=\"kw-def\">HTA</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 300 — Tumeur col-corps utérin</em></p>","frequence":0},{"id":"36-10","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","contenu":"<p>Le profil bénéfices/risques des contraceptifs hormonaux comporte des <strong>effets bénéfiques non contraceptifs</strong> (largement sous-estimés) et des <strong>effets indésirables</strong> dont certains <span class=\"kw-alerte\">engagent le pronostic vital</span> (MTEV, artériel).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Effets bénéfiques de la COP</h4>\n      <table >\n        <thead><tr><th>Domaine</th><th>Effet</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cancers</strong></td><td>↓ <span class=\"kw-clinique\">cancer ovaire</span> (−<span class=\"kw-chiffre\">30 à 50 %</span>), <span class=\"kw-clinique\">cancer endomètre</span> (−<span class=\"kw-chiffre\">50 %</span>, <em>même si CI à la COP</em>), <span class=\"kw-clinique\">cancer côlon-rectum</span></td></tr>\n          <tr><td><strong>Symptômes gynéco</strong></td><td>↓ <span class=\"kw-clinique\">dysménorrhées</span>, <span class=\"kw-clinique\">ménorragies fonctionnelles</span>, <span class=\"kw-clinique\">syndrome prémenstruel</span>, <span class=\"kw-clinique\">acné</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Effets indésirables de la COP</h4>\n      <table >\n        <thead><tr><th>Domaine</th><th>Effet / mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>MTEV</strong></td>\n            <td>\n              Risque thromboembolique veineux × <span class=\"kw-chiffre\">3</span> ; <span class=\"kw-alerte\">COP = FdR majeur transitoire de MTEV</span><br>\n              <strong>Présent avec TOUTES les COP</strong>, hiérarchie de risque :<br>\n              <span class=\"kw-ttt\">2ᵉ gén (lévonorgestrel)</span> : le moins à risque<br>\n              <span class=\"kw-ttt\">3ᵉ gén (norgestimate)</span> : équivalent au lévonorgestrel<br>\n              <span class=\"kw-ttt\">3ᵉ gén autres</span>, <span class=\"kw-ttt\">drospirénone</span>, <span class=\"kw-ttt\">acétate de cyprotérone</span> : <span class=\"kw-alerte\">les plus à risque</span><br>\n              <span class=\"kw-ttt\">Patch / Anneau</span> : risque ≈ 3ᵉ génération\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque artériel</strong><br><em>(<span class=\"kw-def\">IDM</span>, <span class=\"kw-def\">AVC</span>)</em></td>\n            <td>\n              Surtout chez les femmes à risque (action synergique) :<br>\n              <strong>Métabolisme glucidique</strong> : ↓ tolérance glucose → certaine <span class=\"kw-alerte\">insulinorésistance</span><br>\n              <strong>Métabolisme lipidique</strong> : ↑ <span class=\"kw-bio\">TG</span>, <span class=\"kw-bio\">CT</span>, <span class=\"kw-bio\">HDL</span><br>\n              <strong><span class=\"kw-def\">HTA</span></strong> : apparaît chez <span class=\"kw-chiffre\">~5 %</span> des femmes (modification de l'angiotensinogène)<br>\n              <strong>Synergies à risque</strong> : âge <span class=\"kw-chiffre\">&gt; 35 ans</span>, ATCD familial 1ᵉʳ degré jeune (<span class=\"kw-chiffre\">&lt; 60 ans</span>), <span class=\"kw-etio\">obésité</span>/<span class=\"kw-etio\">surpoids</span>, <span class=\"kw-etio\">tabac</span> (dose-dépendant), <span class=\"kw-alerte\">migraine avec aura</span> (effet synergique majeur sur risque <span class=\"kw-clinique\">AVC ischémique</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cancers</strong></td>\n            <td>\n              ↑ très discrète <span class=\"kw-clinique\">cancer du sein</span> (utilisation prolongée)<br>\n              ↑ très discrète <span class=\"kw-clinique\">cancer du col</span> chez les femmes <span class=\"kw-etio\">HPV</span>+ (surtout &gt;<span class=\"kw-chiffre\"> 5 ans</span>)<br>\n              <em>Cancer du foie (information retrouvée dans l'item cancer du sein)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Digestif</strong></td>\n            <td>↑ risque de <span class=\"kw-clinique\">lithiase biliaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>EI mineurs</strong></td>\n            <td>\n              Variables selon climat hormonal et patiente :<br>\n              Troubles du cycle (début), <span class=\"kw-clinique\">mastodynies</span>, troubles de la libido<br>\n              <span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">céphalées</span>/migraines, jambes lourdes<br>\n              <span class=\"kw-clinique\">Acné</span>, <span class=\"kw-clinique\">hirsutisme</span>, hyperplasie gingivale<br>\n              Troubles de l'humeur, chorée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pas d'effet</strong></td>\n            <td><span class=\"kw-alerte\">Pas de prise de poids significative</span> sous pilule</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Microprogestatifs — profil EI</h4>\n      <ul>\n        <li><strong>Avantage majeur</strong> : <span class=\"kw-alerte\">pas d'effets métaboliques ni vasculaires</span> → prescription possible chez les femmes à risque vasculaire.</li>\n        <li>Retour de couches <span class=\"kw-etio\">hémorragique</span> en post-partum (atrophie endomètre).</li>\n        <li>↑ risque de <span class=\"kw-clinique\">GEU</span> (selon gynéco, mais pas selon la HAS).</li>\n        <li><span class=\"kw-clinique\">Troubles du cycle</span>, <span class=\"kw-clinique\">spottings</span>, <span class=\"kw-clinique\">aménorrhée</span> (principal).</li>\n        <li>Dystrophies ovariennes → climat d'hyperœstrogénie relative : syndrome prémenstruel, kystes fonctionnels, signes d'hyperandrogénie (<span class=\"kw-clinique\">acné</span>, <span class=\"kw-clinique\">hirsutisme</span>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">DIU — profil EI</h4>\n      <ul>\n        <li><strong>DIU au cuivre</strong> : <span class=\"kw-clinique\">ménorragies</span>, <span class=\"kw-clinique\">dysménorrhées</span>.</li>\n        <li><strong>DIU au lévonorgestrel</strong> : <span class=\"kw-clinique\">aménorrhée</span> (<span class=\"kw-chiffre\">30-50 %</span>), <span class=\"kw-clinique\">métrorragies</span> (<span class=\"kw-chiffre\">10-15 %</span>), syndrome prémenstruel, kystes ovariens fonctionnels, signes d'hyperandrogénie modérée (séborrhée, acné, hirsutisme).</li>\n        <li><strong>Complications graves (tout DIU)</strong> : infection génitale, expulsion spontanée, perforation (pose douloureuse en cause).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute <span class=\"kw-clinique\">douleur de jambe unilatérale</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">douleur thoracique</span> ou <span class=\"kw-clinique\">déficit neurologique focal</span> sous COP doit faire évoquer une <span class=\"kw-alerte\">MTEV ou un AVC ischémique</span> → arrêt COP + évaluation urgente.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 312 — Tumeur sein · 300 — Tumeur col-corps utérin · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span> · 41 — Endométrisose</em></p>","frequence":1},{"id":"36-11","rang":"B","rubrique":"Prise en charge","titre":"Prescrire les examens complémentaires recommandés à l’initiation d’une contraception estroprogestative","contenu":"<p>Le principe est de <span class=\"kw-alerte\">ne pas prescrire de bilan systématique</span> chez une femme jeune sans particularité — seuls les terrains à risque imposent des examens ciblés.</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Frottis cervico-vaginal (FCV)</span></strong></td>\n            <td>Toute femme <span class=\"kw-chiffre\">≥ 25 ans</span></td>\n            <td>À effectuer tous les <span class=\"kw-chiffre\">3 ans</span> selon les recommandations</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Bilan lipidique</span></strong> (CT, <span class=\"kw-bio\">HDL</span>, <span class=\"kw-bio\">LDL</span>, TG)</td>\n            <td>ATCD familiaux de <span class=\"kw-etio\">dyslipidémie</span> ou d'accidents artériels</td>\n            <td>À renouveler à <span class=\"kw-chiffre\">3-6 mois</span>, puis tous les <span class=\"kw-chiffre\">5 ans</span> en l'absence de fait nouveau</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Glycémie à jeun</span></strong></td>\n            <td>ATCD familiaux de <span class=\"kw-etio\">dyslipidémie</span> ou d'accidents artériels</td>\n            <td>Idem <span class=\"kw-bio\">bilan lipidique</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Bilan de thrombophilie</span></strong></td>\n            <td>ATCD familiaux de MTEV au 1ᵉʳ degré</td>\n            <td>\n              <span class=\"kw-bio\">TP, TCA</span> (<span class=\"kw-ttt\">anticoagulant</span> circulant)<br>\n              <span class=\"kw-bio\">Antithrombine, protéine C, protéine S</span><br>\n              <span class=\"kw-bio\">Test de résistance à la protéine C activée</span><br>\n              <span class=\"kw-bio\">Mutation FV (Leiden)</span>, <span class=\"kw-bio\">mutation FII (prothrombine)</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le bilan <span class=\"kw-ttt\">biologique</span> <span class=\"kw-alerte\">n'est pas systématique</span> à l'instauration de la COP. Il est <strong>ciblé selon les ATCD familiaux</strong> (<span class=\"kw-bio\">CV</span>, MTEV). Pour le FCV, le seuil est l'âge (<span class=\"kw-chiffre\">≥ 25 ans</span>), pas la contraception.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 247 — <span class=\"kw-etio\">Diabète</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 300 — Tumeur col-corps utérin</em></p>","frequence":0},{"id":"36-12","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire les différentes contraceptions disponibles y compris la contraception d’urgence","contenu":"<p>La prescription pratique de chaque méthode contraceptive obéit à des règles précises de <strong>modalité de prise</strong>, <strong>moment d'initiation</strong> et de <strong>protection complémentaire</strong> les premiers jours.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">COP par voie orale</h4>\n      <table >\n        <thead><tr><th>Élément</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Régularité</strong></td>\n            <td>Prise quotidienne <strong>au même moment de la journée</strong>, sans oubli</td>\n          </tr>\n          <tr>\n            <td><strong>1ʳᵉ <span class=\"kw-bio\">plaquette</span></strong></td>\n            <td>\n              Soit entre le <span class=\"kw-chiffre\">1ᵉʳ et 5ᵉ jour des règles</span> → <strong>efficacité immédiate</strong><br>\n              Soit à n'importe quel moment du cycle (<em>quick start</em>) → <span class=\"kw-alerte\">rapports protégés les 7 premiers jours</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Plaquettes</span> suivantes</strong></td>\n            <td>\n              <span class=\"kw-bio\">Plaquette</span> de 21 cp + <span class=\"kw-chiffre\">7 jours d'arrêt</span> entre chaque cycle<br>\n              Ou prise continue : <span class=\"kw-chiffre\">21 cp actifs + 7 placebos</span>, ou <span class=\"kw-chiffre\">24 + 4</span> (minidosée), ou <span class=\"kw-chiffre\">26 + 2</span> (valérate d'œstradiol)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres voies œstroprogestatives</h4>\n      <ul>\n        <li><strong>Patch (<span class=\"kw-ttt\">Evra®</span>)</strong> — <span class=\"kw-chiffre\">1 patch/semaine</span> ×<span class=\"kw-chiffre\"> 3 semaines</span>/4.</li>\n        <li><strong>Anneau vaginal (<span class=\"kw-ttt\">Nuvaring®</span>)</strong> — inséré par la patiente, laissé en place <span class=\"kw-chiffre\">3 semaines</span>, nouvel anneau après <span class=\"kw-chiffre\">1 semaine</span> d'interruption.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception microprogestative orale</h4>\n      <ul>\n        <li>Prise à heure <span class=\"kw-alerte\">strictement fixe</span>.</li>\n        <li>Retard maximum : <span class=\"kw-chiffre\">3h</span> (<span class=\"kw-ttt\">lévonorgestrel</span>) · <span class=\"kw-chiffre\">12h</span> (<span class=\"kw-ttt\">désogestrel</span>) · <span class=\"kw-chiffre\">24h</span> (<span class=\"kw-ttt\">drospirénone</span>).</li>\n        <li>Si retard dépassé : contraception mécanique <strong><span class=\"kw-chiffre\">≥ 1 semaine</span></strong>.</li>\n        <li>Indications de 1ᵉʳ choix : <strong><span class=\"kw-ci\">allaitement</span></strong>, <strong>post-partum immédiat</strong>, <strong>CI métaboliques/vasculaires à la COP</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Implant (<span class=\"kw-ttt\">Nexplanon®</span>)</h4>\n      <p>Pose à la face interne du bras non dominant après anesthésie locale. Durée : <span class=\"kw-chiffre\">3 ans</span>. <strong>Observance parfaite</strong> assurée.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">DIU</h4>\n      <ul>\n        <li><strong>DIU au cuivre</strong> — multiples modèles selon taille utérine ; durée <span class=\"kw-chiffre\">5-10 ans</span>. Possible chez la nullipare avec DIU de petite taille (\"short\" ou \"mini\").</li>\n        <li><strong>DIU au lévonorgestrel</strong> — Mirena®<span class=\"kw-chiffre\"> 52 mg</span> (<span class=\"kw-chiffre\">5 ans</span>), Kyleena®<span class=\"kw-chiffre\"> 19,5 mg</span> (<span class=\"kw-chiffre\">5 ans</span>), Jaydess®<span class=\"kw-chiffre\"> 13,5 mg</span> (<span class=\"kw-chiffre\">3 ans</span>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception d'<span class=\"kw-alerte\">urgence</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Lévonorgestrel</span><span class=\"kw-chiffre\"> 1,5 mg</span></strong> en 1 prise unique — <span class=\"kw-chiffre\">≤ 72h</span>, le plus précocement possible ; vente libre, gratuite pour mineures et majeures.</li>\n        <li><strong><span class=\"kw-ttt\">Acétate d'ulipristal</span><span class=\"kw-chiffre\"> 30 mg</span></strong> per os en 1 prise unique — <span class=\"kw-chiffre\">≤ 120h</span>, plus efficace ; CI <span class=\"kw-ci\">asthme sévère</span>, <span class=\"kw-ci\">insuffisance hépatique</span>.</li>\n        <li><strong>DIU au cuivre</strong> — <span class=\"kw-chiffre\">≤ 120h</span> ; le plus efficace + contraception durable.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 37 — IVG</em></p>","frequence":4},{"id":"36-13","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","contenu":"<p>L'efficacité d'une méthode contraceptive se mesure par l'<span class=\"kw-def\">indice de Pearl</span> : <strong>nombre de grossesses accidentelles pour 100 femmes après <span class=\"kw-chiffre\">12 mois</span> d'utilisation</strong>. Plus l'indice est faible, plus la méthode est efficace.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Indice de Pearl = taux de <span class=\"kw-ci\">grossesse</span> pour <span class=\"kw-chiffre\">100 couples</span> exposés à un mode de contraception sur une durée de <span class=\"kw-chiffre\">12 mois</span>. <span class=\"kw-alerte\">Meilleur si faible</span>.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Efficacité des différentes méthodes (OMS 2015)</h4>\n      <p>Pourcentage de femmes concernées par une <span class=\"kw-ci\">grossesse</span> non intentionnelle durant la première année d'utilisation, selon usage <em>courant</em> (réel) ou <em>parfait</em> (théorique).</p>\n\n      <table >\n        <thead>\n          <tr><th>Méthode</th><th>Utilisation courante (%)</th><th>Utilisation parfaite (%)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Aucune méthode</strong></td><td><span class=\"kw-chiffre\">85</span></td><td><span class=\"kw-chiffre\">85</span></td></tr>\n          <tr><td><strong>Pilules combinées œstroprogestatives</strong> (orale, patch, anneau)</td><td><span class=\"kw-chiffre\">8</span></td><td><span class=\"kw-chiffre\">0,3</span></td></tr>\n          <tr><td><strong>Pilules microprogestatives</strong></td><td><span class=\"kw-chiffre\">8</span></td><td><span class=\"kw-chiffre\">0,3</span></td></tr>\n          <tr><td><strong>Implant au lévonorgestrel</strong></td><td><span class=\"kw-chiffre\">0,05</span></td><td><span class=\"kw-chiffre\">0,05</span></td></tr>\n          <tr><td><strong>DIU au cuivre</strong></td><td><span class=\"kw-chiffre\">0,8</span></td><td><span class=\"kw-chiffre\">0,6</span></td></tr>\n          <tr><td><strong>DIU au lévonorgestrel</strong></td><td><span class=\"kw-chiffre\">0,1</span></td><td><span class=\"kw-chiffre\">0,1</span></td></tr>\n          <tr><td><strong>Préservatifs masculins</strong></td><td><span class=\"kw-chiffre\">15</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><strong>Préservatifs féminins</strong></td><td><span class=\"kw-chiffre\">21</span></td><td><span class=\"kw-chiffre\">5</span></td></tr>\n          <tr><td><strong>Retrait</strong></td><td><span class=\"kw-chiffre\">27</span></td><td><span class=\"kw-chiffre\">4</span></td></tr>\n          <tr><td><strong>Spermicides, tampons, éponges</strong></td><td><span class=\"kw-chiffre\">29</span></td><td><span class=\"kw-chiffre\">18</span></td></tr>\n          <tr><td><strong>Diaphragme</strong></td><td><span class=\"kw-chiffre\">16</span></td><td><span class=\"kw-chiffre\">6</span></td></tr>\n          <tr><td><strong>Cape</strong> (uni/multipares)</td><td><span class=\"kw-chiffre\">32</span></td><td><span class=\"kw-chiffre\">20</span></td></tr>\n          <tr><td><strong>Cape</strong> (nullipares)</td><td><span class=\"kw-chiffre\">16</span></td><td><span class=\"kw-chiffre\">9</span></td></tr>\n          <tr><td><strong>Stérilisation féminine</strong></td><td><span class=\"kw-chiffre\">0,5</span></td><td><span class=\"kw-chiffre\">0,5</span></td></tr>\n          <tr><td><strong>Stérilisation masculine</strong></td><td><span class=\"kw-chiffre\">0,15</span></td><td><span class=\"kw-chiffre\">0,10</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Contraception d'<span class=\"kw-alerte\">urgence</span> — niveaux d'efficacité</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">DIU au cuivre</span></strong> — le plus efficace (≈<span class=\"kw-chiffre\"> 99 %</span>), efficacité jusqu'à <span class=\"kw-chiffre\">120h</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Acétate d'ulipristal</span></strong> — plus efficace que le lévonorgestrel, jusqu'à <span class=\"kw-chiffre\">120h</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Lévonorgestrel</span></strong> — d'autant plus efficace que pris précocement, jusqu'à <span class=\"kw-chiffre\">72h</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Méthodes les plus efficaces (Pearl <span class=\"kw-chiffre\">≤ 1</span>) : <strong>implant</strong>, <strong>DIU au lévonorgestrel</strong>, <strong>DIU au cuivre</strong>, <strong>stérilisations</strong>. La différence courant/parfait montre l'<strong>impact de l'observance</strong> (COP :<span class=\"kw-chiffre\"> 8 %</span> <span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 0,3 %</span>).\n      </div>","frequence":1},{"id":"36-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître et savoir expliciter à la patiente la conduite à tenir en cas d’oubli de pilule","contenu":"<p>L'oubli de pilule est une situation fréquente — la CAT dépend de <strong>3 facteurs déterminants</strong> :</p>\n      <ul>\n        <li><strong>Type de contraception</strong> — COP combinée <span class=\"kw-bio\">vs</span> microprogestative.</li>\n        <li><strong>Moment de la <span class=\"kw-bio\">plaquette</span></strong> où est survenu l'oubli.</li>\n        <li><strong>Rapports sexuels ou non dans les <span class=\"kw-chiffre\">5 jours</span> précédant</strong> l'oubli.</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/36/cat-oubli-pilule.png\" alt=\"Algorithme de conduite à tenir en cas d'oubli de pilule selon le type de contraception (COP ou microprogestative), le moment de la plaquette et les rapports sexuels dans les 5 jours précédant\" loading=\"lazy\">\n        <figcaption>Arbre décisionnel — CAT en cas d'oubli de pilule. Source : fiche source EDN item 36 (Collège gynécologie-obstétrique).</figcaption>\n      </figure>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principes généraux à retenir (COP)</h4>\n      <ul>\n        <li><strong>Oubli <span class=\"kw-chiffre\">&lt; 12h</span></strong> → prendre le comprimé oublié immédiatement + poursuivre la <span class=\"kw-bio\">plaquette</span> normalement. <strong>Pas de contraception complémentaire</strong>.</li>\n        <li><strong>Oubli <span class=\"kw-chiffre\">≥ 12h</span></strong> ou <strong><span class=\"kw-chiffre\">≥ 2</span> comprimés oubliés</strong> → prendre immédiatement le dernier comprimé oublié + poursuivre la <span class=\"kw-bio\">plaquette</span> + <strong>préservatif pendant <span class=\"kw-chiffre\">7 jours</span></strong>.</li>\n        <li>Si rapport sexuel dans les <span class=\"kw-chiffre\">5 jours</span> précédant l'oubli <span class=\"kw-chiffre\">≥ 12h</span> → <strong>contraception d'<span class=\"kw-alerte\">urgence</span></strong> indiquée.</li>\n        <li>Si oubli en fin de <span class=\"kw-bio\">plaquette</span> (3ᵉ semaine) → enchaîner directement sur la plaquette suivante <strong>sans pause</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Microprogestatifs — règles plus strictes</h4>\n      <ul>\n        <li>Retard toléré : <span class=\"kw-chiffre\">3h</span> (<span class=\"kw-ttt\">lévonorgestrel</span>), <span class=\"kw-chiffre\">12h</span> (<span class=\"kw-ttt\">désogestrel</span>), <span class=\"kw-chiffre\">24h</span> (<span class=\"kw-ttt\">drospirénone</span>).</li>\n        <li>Au-delà : <strong>préservatif pendant <span class=\"kw-chiffre\">7 jours</span></strong> + <strong>contraception d'<span class=\"kw-alerte\">urgence</span></strong> si rapport non protégé dans les <span class=\"kw-chiffre\">5 jours</span> précédents.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fréquent.</strong> L'oubli en <strong>1ʳᵉ semaine</strong> de <span class=\"kw-bio\">plaquette</span> COP est le plus à risque de <span class=\"kw-ci\">grossesse</span> (chevauche la levée de l'inhibition gonadotrope) — penser CU même si oubli isolé si rapport récent.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 37 — IVG</em></p>","frequence":0},{"id":"36-15","rang":"B","rubrique":"Prise en charge","titre":"Être capable d’expliciter à la patiente les avantages et inconvénients des différentes contraceptions","contenu":"<p>Le choix d'une méthode contraceptive est partagé avec la patiente. Pour l'orienter, il faut connaître les <strong>avantages et inconvénients propres à chaque méthode</strong>, et la mettre en regard du <strong>profil clinique et du mode de vie</strong>.</p>\n\n      <table >\n        <thead><tr><th>Méthode</th><th>Avantages</th><th>Inconvénients</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>COP orale</strong></td>\n            <td>\n              Efficacité élevée (Pearl <span class=\"kw-chiffre\">0,3 %</span>)<br>\n              Bénéfices non contraceptifs : cycles réguliers, ↓ dysménorrhée, ↓ acné, ↓ cancer ovaire/endomètre/colon\n            </td>\n            <td>\n              Observance quotidienne contraignante<br>\n              <span class=\"kw-alerte\">Risque MTEV</span>, <span class=\"kw-alerte\">artériel</span><br>\n              ↑ discret cancer du sein et col<br>\n              EI mineurs (<span class=\"kw-clinique\">céphalées</span>, mastodynies, troubles cycle)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Patch / Anneau</strong></td>\n            <td>Meilleure observance que voie orale</td>\n            <td>Mêmes CI et EI que COP orale ; risque MTEV ≈ 3ᵉ génération</td>\n          </tr>\n          <tr>\n            <td><strong>Microprogestatifs oraux</strong></td>\n            <td>\n              Pas d'effets métaboliques/vasculaires<br>\n              Possibles si CI à la COP, <span class=\"kw-ci\">allaitement</span>, post-partum\n            </td>\n            <td>\n              Heure stricte de prise<br>\n              Troubles du cycle, spottings, <span class=\"kw-clinique\">aménorrhée</span><br>\n              Signes hyperandrogénie (<span class=\"kw-clinique\">acné</span>, <span class=\"kw-clinique\">hirsutisme</span>), kystes fonctionnels\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Implant</strong></td>\n            <td>\n              Pearl <span class=\"kw-chiffre\">0,05 %</span> (le plus efficace)<br>\n              Observance parfaite × <span class=\"kw-chiffre\">3 ans</span><br>\n              Pas d'effets métaboliques/vasculaires\n            </td>\n            <td>\n              Geste de pose et retrait<br>\n              Troubles du cycle, spottings, aménorrhée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU cuivre</strong></td>\n            <td>\n              Pearl 0,8 /<span class=\"kw-chiffre\"> 0,6 %</span><br>\n              Non hormonal, longue durée (<span class=\"kw-chiffre\">5-10 ans</span>)<br>\n              Réversible\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Ménorragies</span>, <span class=\"kw-clinique\">dysménorrhées</span><br>\n              CI infectieuses récentes<br>\n              Risque rare d'expulsion/perforation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU lévonorgestrel</strong></td>\n            <td>\n              Pearl <span class=\"kw-chiffre\">0,1 %</span><br>\n              Spécialement indiqué si <span class=\"kw-clinique\">dysménorrhée</span>, <span class=\"kw-clinique\">ménorragies</span>, <span class=\"kw-etio\">adénomyose</span>\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Aménorrhée</span><span class=\"kw-chiffre\"> 30-50 %</span>, métrorragies, syndrome prémenstruel<br>\n              CI si cancer du sein\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Préservatif</strong></td>\n            <td><span class=\"kw-alerte\">Seule méthode protégeant des IST</span> ; vente libre</td>\n            <td>Pearl <span class=\"kw-chiffre\">15 %</span> /<span class=\"kw-chiffre\"> 2 %</span> (dépendant utilisation) ; <span class=\"kw-alerte\">rupture</span> possible</td>\n          </tr>\n          <tr>\n            <td><strong>Méthodes naturelles</strong></td>\n            <td>Pas d'EI, pas de produit chimique</td>\n            <td><span class=\"kw-alerte\">Faible efficacité</span> chez les femmes fertiles</td>\n          </tr>\n          <tr>\n            <td><strong>Stérilisation</strong></td>\n            <td>Pearl <span class=\"kw-chiffre\">0,5 %</span> (femme) /<span class=\"kw-chiffre\"> 0,15 %</span> (homme), définitif</td>\n            <td>Caractère <strong>irréversible</strong>, délai légal <span class=\"kw-chiffre\">4 mois</span>, regrets possibles si post-partum immédiat</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'observance est <strong>la première condition</strong> d'efficacité. Une méthode imparfaitement adaptée au mode de vie de la patiente sera moins efficace en pratique qu'une méthode théoriquement moins puissante mais bien suivie.\n      </div>","frequence":0},{"id":"36-16","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les interactions potentielles médicamenteuses","contenu":"<p>Les <span class=\"kw-def\">interactions médicamenteuses</span> avec la contraception hormonale agissent soit en <strong>diminuant l'efficacité contraceptive</strong> (inducteurs enzymatiques), soit en perturbant un <strong>traitement associé</strong> (cas de la <span class=\"kw-ttt\">lamotrigine</span>).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Inducteurs enzymatiques — ↓ efficacité COP</h4>\n      <p>Les inducteurs enzymatiques accélèrent le métabolisme hépatique des stéroïdes contraceptifs → <span class=\"kw-alerte\">diminution de l'efficacité contraceptive</span>. Moyen mnémo : <strong><span class=\"kw-ttt\">PRECaMPaGNe</span></strong>.</p>\n      <ul>\n        <li><strong>P</strong> — <span class=\"kw-ttt\">Phénytoïne</span></li>\n        <li><strong>R</strong> — <span class=\"kw-ttt\">Rifampicine</span> / <span class=\"kw-ttt\">Rifabutine</span></li>\n        <li><strong>E / Ca</strong> — <span class=\"kw-ttt\">Éfavirenz</span> / <span class=\"kw-ttt\">Carbamazépine</span></li>\n        <li><strong>M</strong> — <span class=\"kw-ttt\">Modafinil</span></li>\n        <li><strong>Pa</strong> — <span class=\"kw-ttt\">Phénobarbital</span></li>\n        <li><strong>G</strong> — <span class=\"kw-ttt\">Griséofulvine</span></li>\n        <li><strong>Ne</strong> — <span class=\"kw-ttt\">Névirapine</span></li>\n        <li>Autres : <span class=\"kw-ttt\">millepertuis</span>, <span class=\"kw-ttt\">topiramate</span>, certains antiprotéases du <span class=\"kw-etio\">VIH</span></li>\n      </ul>\n\n      <p>CAT en cas de prise d'un inducteur : utiliser une <strong>contraception mécanique associée</strong> ou changer pour une méthode non hormonale (<span class=\"kw-ttt\">DIU cuivre</span>).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cas particulier de la <span class=\"kw-ttt\">lamotrigine</span></h4>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Les COP <strong>accélèrent le métabolisme de la <span class=\"kw-ttt\">lamotrigine</span></strong> → <span class=\"kw-alerte\">diminution de sa concentration plasmatique</span> → <span class=\"kw-alerte\">recrudescence des crises d'épilepsie</span>. Si association nécessaire : <span class=\"kw-def\">surveillance</span> clinique rapprochée + adaptation posologique (<em>néanmoins l'association reste possible sous réserve d'une surveillance — point parfois nuancé en QCM</em>).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres interactions à connaître</h4>\n      <ul>\n        <li><strong>Antibiotiques à large spectre</strong> — pas d'interaction démontrée hors <span class=\"kw-ttt\">rifampicine</span>/rifabutine, mais en pratique courante : conseiller un préservatif additionnel pendant la cure et <span class=\"kw-chiffre\">7 jours</span> après.</li>\n        <li><strong>Antifongiques (ex : griséofulvine)</strong> — diminuent l'efficacité.</li>\n        <li><strong>Antirétroviraux</strong> — interactions complexes ; concertation infectiologie.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 105 — Epilepsie · 326 — Cadre réglementaire de la prescription et reco pour bon usage · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"36-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les éléments de suivi (cliniques et biologiques) d’une contraception hormonale ou intra-utérine","contenu":"<p>Le <span class=\"kw-def\">suivi</span> d'une contraception hormonale ou intra-utérine est <strong>structuré</strong>, à vie tant que la contraception est utilisée. Il vise à dépister les EI, vérifier la tolérance et l'observance, et adapter la prescription.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Suivi</span> clinique (identique à l'évaluation pré-prescription)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Examen mammaire</span>.</li>\n        <li><span class=\"kw-clinique\">Pression artérielle</span>.</li>\n        <li><span class=\"kw-clinique\">IMC</span> (poids, taille).</li>\n        <li>Recherche d'EI (<span class=\"kw-clinique\">céphalées</span>, jambes lourdes, troubles cycle, mastodynies, troubles humeur).</li>\n        <li>Vérification de l'observance et de la tolérance.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Rythme du <span class=\"kw-def\">suivi</span> clinique</h4>\n      <ul>\n        <li><strong>1ʳᵉ <span class=\"kw-def\">consultation de suivi</span> : à <span class=\"kw-chiffre\">3 mois</span></strong>.</li>\n        <li>Puis <strong><span class=\"kw-chiffre\">1×/an</span></strong> (selon endocrinologue : <span class=\"kw-chiffre\">M3</span> → M6 → puis tous les <span class=\"kw-chiffre\">6 mois</span>).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Suivi</span> paraclinique</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Rythme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Bilan lipidique</span> + <span class=\"kw-bio\">glycémie à jeun</span></strong></td>\n            <td>À <span class=\"kw-chiffre\">3-6 mois</span> après instauration, puis tous les <span class=\"kw-chiffre\">5 ans</span> en l'absence de fait nouveau</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Frottis cervico-vaginal</span></strong></td>\n            <td>Tous les <span class=\"kw-chiffre\">3 ans</span> (selon recommandations <span class=\"kw-def\">dépistage</span> cancer du col, à partir de <span class=\"kw-chiffre\">25 ans</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Particularités selon la méthode</h4>\n      <ul>\n        <li><strong>DIU</strong> — visite de contrôle <span class=\"kw-chiffre\">4-6 semaines</span> après pose, puis 1×/an ; vérification des fils.</li>\n        <li><strong>Implant</strong> — contrôle de la position après pose ; retrait à <span class=\"kw-chiffre\">3 ans</span>.</li>\n        <li><strong>Macroprogestatifs</strong> — <span class=\"kw-def\">surveillance</span> ANSM : <span class=\"kw-imagerie\">IRM cérébrale</span> en raison du risque de <span class=\"kw-alerte\">méningiome</span> si utilisation prolongée.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le bilan <span class=\"kw-ttt\">biologique</span> est <strong>ciblé selon le <span class=\"kw-def\">terrain</span></strong>, pas systématique. Le <span class=\"kw-def\">suivi</span> clinique annuel reste indispensable même chez la femme sans FdR.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":1},{"id":"36-18","rang":"B","rubrique":"Prise en charge","titre":"Savoir prescrire une contraception chez les femmes à risque vasculaire","contenu":"<p>Chez les femmes à risque vasculaire (<span class=\"kw-bio\">CV</span> ou MTEV), la <span class=\"kw-def\">COP est généralement contre-indiquée</span>. L'alternative repose sur les <strong>microprogestatifs</strong> et le <strong>DIU</strong>, sans retentissement métabolique ni vasculaire.</p>\n\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Particularités</th><th>Contraception adaptée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Diabète</span></strong></td>\n            <td>\n              Grossesses doivent être <strong>planifiées impérativement</strong><br>\n              Risque métabolique et vasculaire à considérer\n            </td>\n            <td>\n              <strong>COP <span class=\"kw-ci\">contre-indiquée</span></strong> si <span class=\"kw-def\">DT1</span> compliqué ou <span class=\"kw-def\">DT1</span> <span class=\"kw-chiffre\">&gt; 20 ans</span><br>\n              Préférer <span class=\"kw-ttt\">microprogestatif</span> ou <span class=\"kw-ttt\">DIU</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Dyslipidémie</span></strong></td>\n            <td>\n              COP peu d'effet si normolipidémie<br>\n              COP peut <strong>↑ significativement les lipides</strong> chez la dyslipidémique\n            </td>\n            <td>\n              COP possible jusqu'à <span class=\"kw-chiffre\">3 g/L de cholestérol total</span> si pas d'autre <span class=\"kw-etio\">FRCV</span> (<span class=\"kw-etio\">tabac</span>), âge <span class=\"kw-chiffre\">&lt; 35 ans</span>, diététique adaptée<br>\n              Sinon <span class=\"kw-ttt\">microprogestatif</span> ou <span class=\"kw-ttt\">DIU</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">HTA</span></strong></td>\n            <td>\n              Contraceptifs oraux → ↑ modérée PA<br>\n              <span class=\"kw-chiffre\">&lt; 5 %</span> des utilisatrices présentent une <span class=\"kw-def\">HTA</span> sous OP\n            </td>\n            <td>\n              <strong><span class=\"kw-def\">HTA</span> = <span class=\"kw-ci\">CI absolue aux œstroprogestatifs</span></strong><br>\n              <span class=\"kw-ttt\">Microprogestatif</span>, <span class=\"kw-ttt\">DIU cuivre</span>, <span class=\"kw-ttt\">DIU lévonorgestrel</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque de MTEV</strong></td>\n            <td>\n              Bilan de thrombophilie avant mise sous COP<br>\n              ATCD MTEV ou anomalie hémostase\n            </td>\n            <td>\n              <strong>COP <span class=\"kw-ci\">contre-indiquée</span></strong> en cas d'ATCD MTEV ou anomalie hémostase<br>\n              <span class=\"kw-ttt\">Contraceptions progestatives seules</span>, <span class=\"kw-ttt\">DIU cuivre</span>, <span class=\"kw-ttt\">DIU lévonorgestrel</span> : possibles\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Questionnaire ANSM de <span class=\"kw-def\">dépistage</span> du risque vasculaire</h4>\n      <p>Avant toute prescription d'une COP, le clinicien doit dépister les FdR vasculaires via un questionnaire structuré ANSM (février 2014). Si <strong>au moins une <span class=\"kw-ci\">CI absolue</span></strong> (ATCD personnel ou actuel thrombose/<span class=\"kw-def\">IDM</span>/<span class=\"kw-def\">AVC</span>/<span class=\"kw-def\">AIT</span>/<span class=\"kw-clinique\">angor</span>, trouble personnel coagulation, <span class=\"kw-def\">migraine</span> avec aura, <span class=\"kw-def\">diabète</span> compliqué, PA <span class=\"kw-chiffre\">≥ 160/100 mmHg</span>, hyperlipidémie importante, intervention chirurgicale majeure ou immobilisation programmée) → <span class=\"kw-alerte\">ne pas prescrire</span>. Si <span class=\"kw-ci\">CI relatives</span> (IMC <span class=\"kw-chiffre\">&gt; 30</span>, âge <span class=\"kw-chiffre\">&gt; 35</span>, <span class=\"kw-etio\">tabac</span>, PA 140-159/90-99, ATCD MTEV familial jeune…) → vérifier la pertinence avec la patiente.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-etio\">Diabète</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span> · 99 — <span class=\"kw-def\">Migraine</span> - névralgie trijumeau - algie face</em></p>","frequence":3},{"id":"36-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription chez la jeune femme mineure","contenu":"<p>La prescription contraceptive chez la <strong>jeune fille mineure</strong> obéit à un cadre légal protecteur, visant à garantir l'<strong>accès gratuit, confidentiel et sans formalité parentale</strong>. Objectif : permettre une contraception en toute sécurité et discrétion.</p>\n\n      <table >\n        <thead><tr><th>Élément</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Accès facilité pour les jeunes filles <strong>mineures de <span class=\"kw-chiffre\">15-18 ans</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Secret</strong></td>\n            <td>\n              Secret sur l'ensemble du parcours (ni obligatoire ni automatique)<br>\n              Ne dispense pas de communiquer identité et âge, ni de présenter carte Vitale/attestation de droits<br>\n              Si impossibilité : procédure exceptionnelle d'anonymat\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Parents / autorité parentale</strong></td>\n            <td><span class=\"kw-alerte\">Consentement des titulaires de l'autorité parentale NON nécessaire</span> à la prescription d'une contraception hormonale à une mineure ; ni d'aucune autre personne adulte ayant autorité</td>\n          </tr>\n          <tr>\n            <td><strong>Examen gynécologique</strong></td>\n            <td>Réalisé <strong>uniquement si la jeune fille le souhaite</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Tiers payant</strong></td>\n            <td>\n              Consultations (médecin ou sage-femme) : 1ʳᵉ consultation + 1 consultation <span class=\"kw-def\">suivi</span> 1ʳᵉ année puis 1/an<br>\n              Actes : pose, changement, retrait d'un contraceptif<br>\n              Examens biologiques : maximum <span class=\"kw-chiffre\">1/an</span><br>\n              Délivrance des contraceptifs remboursables sur prescription\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Délivrance gratuite</strong></td>\n            <td>\n              Toutes jeunes filles mineures <span class=\"kw-chiffre\">15-18 ans</span><br>\n              Prescription avec mention « <strong>contraception mineure</strong> »<br>\n              Tiers payant + confidentialité (dispositif spécifique)<br>\n              <strong>Code exonération <span class=\"kw-ttt\">EXO 3</span></strong> utilisé systématiquement par le pharmacien<br>\n              NIR anonyme à la facturation : pas de visibilité sur le relevé de remboursement (papier ou Ameli)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>DIU</strong></td>\n            <td><span class=\"kw-alerte\">N'est plus une CI chez la nullipare</span> — DIU de petite taille (\"short\" ou \"mini\") possible chez la jeune fille</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Mention <strong>« contraception mineure »</strong> sur l'ordonnance + code <strong><span class=\"kw-ttt\">EXO 3</span></strong> en pharmacie = clé de la gratuité totale et de la confidentialité.\n      </div>","frequence":0},{"id":"36-20","rang":"A","rubrique":"Définition","titre":"Connaître les différents modes de stérilisation féminine et masculine et l’existence d’une législation","contenu":"<p>La <span class=\"kw-def\">stérilisation à visée contraceptive</span> est une méthode <strong>définitive</strong>, encadrée par des textes juridiques stricts visant à garantir le caractère éclairé du consentement.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre législatif (commun homme/femme)</h4>\n      <table >\n        <thead><tr><th>Élément</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td>Adulte (<strong>majeur·e</strong>) obligatoire</td></tr>\n          <tr><td><strong>Si tutelle ou curatelle</strong></td><td>Décision soumise au <strong>juge des tutelles</strong> après avoir entendu le représentant légal</td></tr>\n          <tr><td><strong>1ʳᵉ consultation</strong></td><td>Demande motivée + délivrance par le médecin d'un <strong>dossier d'information écrit</strong> et d'une <strong>attestation de consultation médicale</strong></td></tr>\n          <tr><td><strong>Délai de réflexion</strong></td><td><strong><span class=\"kw-chiffre\">4 mois</span> obligatoire</strong></td></tr>\n          <tr><td><strong>2ᵉ consultation</strong></td><td>Confirmation <strong>par écrit</strong> du consentement éclairé</td></tr>\n          <tr><td><strong>Lieu</strong></td><td>Établissement de santé (hôpital ou clinique)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Stérilisation féminine</h4>\n      <ul>\n        <li><strong>Méthode cœlioscopique</strong> (seule envisageable, <strong>sous AG</strong>, <strong>efficacité immédiate</strong>) :\n          <ul>\n            <li>Pose de <strong>clip tubaire</strong> ou d'<strong>anneau tubaire</strong></li>\n            <li><strong>Section-ligature</strong> des trompes</li>\n          </ul>\n        </li>\n        <li><strong>Méthode hystéroscopique (dispositif <span class=\"kw-ttt\">Essure®</span>)</strong> — pose d'un <span class=\"kw-ttt\">stent</span> dans chaque trompe entraînant une fibrose irréversible. <span class=\"kw-alerte\">N'est plus disponible en France depuis 2017</span> en raison d'allergies au nickel composant le stent.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Stérilisation masculine — vasectomie bilatérale</h4>\n      <ul>\n        <li>Sous anesthésie <strong>locale, locorégionale ou générale</strong>.</li>\n        <li>Section d'une portion de chacun des <strong>2 canaux déférents</strong>.</li>\n        <li><strong>Cryoconservation du sperme au <span class=\"kw-ttt\">CECOS</span></strong> proposable au patient <strong>avant</strong> le geste (centre d'étude et de conservation des œufs et du sperme).</li>\n        <li><span class=\"kw-alerte\">Efficacité non immédiate</span> : <span class=\"kw-chiffre\">90 jours</span> ; maintenir une <strong>autre contraception pendant <span class=\"kw-chiffre\">12 semaines</span></strong>, le temps de <span class=\"kw-chiffre\">&gt; 30 éjaculations</span>.</li>\n        <li><strong><span class=\"kw-bio\">Spermogramme de contrôle</span></strong> indispensable pour arrêter l'autre contraception. Critère d'efficacité : <span class=\"kw-bio\">azoospermie</span> ou <span class=\"kw-chiffre\">&lt; 100 000 spz/ml non mobiles</span>. Si <span class=\"kw-chiffre\">&gt; 100 000/ml</span> ou spz mobiles → <strong>refaire un spermogramme</strong>.</li>\n        <li><span class=\"kw-alerte\">Irréversible / définitive</span> (pas de solution d'occlusion temporaire validée).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège fréquent.</strong> La stérilisation s'accompagne <strong>plus souvent de regrets</strong> lorsqu'elle est réalisée dans le <strong>post-partum immédiat</strong> (au moment d'une césarienne ou <span class=\"kw-chiffre\">24-48h</span> après accouchement). À évoquer mais à entourer de précautions psychologiques.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le délai obligatoire de <strong><span class=\"kw-chiffre\">4 mois</span></strong> entre la 1ʳᵉ consultation et l'acte est <span class=\"kw-alerte\">non négociable</span>. L'absence de respect de ce délai entache la validité du consentement.\n      </div>","frequence":2,"liens":[{"href":"https://fr.wikipedia.org/wiki/Vasectomie","label":"Wikipedia — Vasectomie"}]}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">MTEV</span> (TVP, EP) : antécédent personnel → <span class=\"kw-ci\">COP contre-indiquée</span> absolument</li><li><span class=\"kw-alerte\">IDM / AVC ischémique / AOMI</span> : antécédents personnels ou familiaux (&lt;<span class=\"kw-chiffre\"> 50 ans</span>) → <span class=\"kw-ci\">COP contre-indiquée</span></li><li><span class=\"kw-alerte\">Migraine avec aura</span> → <span class=\"kw-ci\">COP contre-indiquée</span> (synergie <span class=\"kw-alerte\">AVC</span> <span class=\"kw-etio\">ischémique</span>)</li><li><span class=\"kw-alerte\">HTA</span> (même traitée et équilibrée) → <span class=\"kw-ci\">COP contre-indiquée</span></li><li><span class=\"kw-alerte\">Cancer du sein</span> (y compris non hormonodépendant) → <span class=\"kw-ci\">CI à toute contraception hormonale estrogénique</span></li><li>Questionnaire <span class=\"kw-def\">ANSM</span> (février 2014) à remplir avant toute prescription de <span class=\"kw-def\">COP</span> : cocher <span class=\"kw-chiffre\">≥ 1</span> case section 1 → <span class=\"kw-ci\">contre-indication formelle</span></li></ul>","principes":"<p>Choix personnalisé selon le <span class=\"kw-etio\">terrain</span> et les <span class=\"kw-etio\">facteurs de risque vasculaire</span>. Laisser le choix à la patiente après information et élimination des CI.</p><p><strong>Femme sans <span class=\"kw-def\">facteur de risque</span></strong></p><p>Si <span class=\"kw-chiffre\">≥ 25 ans</span> : <span class=\"kw-bio\">frottis cervico-vaginal</span> tous les <span class=\"kw-chiffre\">3 ans</span></p><ul><li><span class=\"kw-ttt\">COP 2e génération</span> par voie orale : <span class=\"kw-chiffre\">1ère intention</span> (<span class=\"kw-etio\">lévonorgestrel</span> ou <span class=\"kw-etio\">norgestimate</span> — moindre risque <span class=\"kw-alerte\">MTEV</span>)</li><li>Bilan paraclinique avant instauration : <strong>aucun</strong> si <span class=\"kw-def\">terrain</span> sans particularité</li></ul><p><strong>Femme à risque vasculaire / FR métabolique</strong></p><p><span class=\"kw-bio\">Bilan de thrombophilie</span> si ATCD familiaux de MTEV (1er degré) avant tout démarrage</p><ul><li><span class=\"kw-ci\">COP contre-indiquée</span> (MTEV, <span class=\"kw-alerte\">IDM</span>/<span class=\"kw-alerte\">AVC</span>, migraine avec aura, <span class=\"kw-etio\">HTA</span>, DT1 compliqué)</li><li><span class=\"kw-ttt\">Microprogestatif oral</span> (désogestrel, drospirénone) ou <span class=\"kw-ttt\">DIU au lévonorgestrel</span> ou <span class=\"kw-ttt\">DIU au cuivre</span> : alternatives possibles</li><li>Pas d'effets indésirables métaboliques et vasculaires avec les <span class=\"kw-ttt\">microprogestatifs</span></li></ul><p><strong>Post-partum / <span class=\"kw-ci\">allaitement</span></strong></p><ul><li><span class=\"kw-ci\">COP contre-indiquée</span> avant le <span class=\"kw-chiffre\">3e mois</span> post-partum (risque <span class=\"kw-etio\">thrombotique</span> majoré + ablactation)</li><li><span class=\"kw-ttt\">Microprogestatif</span> possible dès le <span class=\"kw-chiffre\">21e jour</span> post-partum (voie orale ou implant)</li><li><span class=\"kw-ttt\">DIU</span> : pose idéale après <span class=\"kw-chiffre\">3 mois</span> (taux d'expulsion élevé si pose immédiate)</li></ul><p><strong>Adolescente (<span class=\"kw-chiffre\">15–18 ans</span>)</strong></p><ul><li>Consentement parental <strong>non requis</strong> pour la prescription</li><li>Examen gynécologique <strong>uniquement si la jeune fille le souhaite</strong></li><li>Contraceptif gratuit et confidentiel sur prescription avec mention « contraception mineure »</li><li><span class=\"kw-ttt\">DIU</span> : n'est plus une CI chez la nullipare</li></ul><p><strong>Contraception d'<span class=\"kw-alerte\">urgence</span></strong></p><p><span class=\"kw-ci\">Pas de contre-indication</span> au lévonorgestrel ; informer que l'efficacité est d'autant plus grande que la prise est précoce</p><ul><li><span class=\"kw-chiffre\">≤ 72h</span> : <span class=\"kw-ttt\">lévonorgestrel</span> forte dose (prise unique) — vente libre, gratuit pour toutes les femmes</li><li><span class=\"kw-chiffre\">≤ 120h (5 j)</span> : <span class=\"kw-ttt\">acétate d'ulipristal</span> (prise unique per os) — plus efficace ; <span class=\"kw-ci\">CI : asthme sévère, insuffisance hépatique</span></li><li><span class=\"kw-chiffre\">≤ 120h</span> : <span class=\"kw-ttt\">DIU au cuivre</span> — <span class=\"kw-chiffre\">1ère intention</span>, le plus efficace, assure ensuite une contraception longue durée</li><li>Mécanisme : inhibition/retard ovulation ; <strong>non contragestif</strong> (ne provoque pas d'avortement)</li></ul>","suivi":"<p><strong>COP — après instauration :</strong> consultation à <span class=\"kw-chiffre\">3 mois</span> puis <span class=\"kw-chiffre\">1×/an</span> (examen clinique : PA · IMC · examen mammaire).<br><strong>Bilan paraclinique :</strong> <span class=\"kw-bio\">bilan lipidique</span> + <span class=\"kw-bio\">glycémie à jeun</span> à <span class=\"kw-chiffre\">3-6 mois</span>, puis tous les <span class=\"kw-chiffre\">5 ans</span> en l'absence de fait nouveau.<br><strong>DIU :</strong> contrôle échographique post-pose recommandé ; <span class=\"kw-def\">surveillance</span> du fil au spéculum à chaque consultation annuelle.<br><strong>ATCD familiaux de <span class=\"kw-etio\">dyslipidémie</span> ou d'accident artériel :</strong> <span class=\"kw-bio\">bilan lipidique + glycémie</span> avant instauration.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-1-item-36-contraception-masculine/","label":"Collège AFU — Contraception masculine (chap. 1, item 36)"},{"href":"https://fac.umc.edu.dz/snv/faculte/BA/2020/1%20la%20spermatogenèse%20cours%20.pdf","label":"UMC — Cours spermatogenèse (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Oubli de pilule — quelle CAT ? — Trois variables : type de pilule · délai de l'oubli · rapports dans les 5 jours précédents","detail":"<h4>CAT — oubli de pilule — Type de contraception · délai de l'oubli · rapport récent</h4>","branches":[{"to":"q-cop-delai","label":"Pilule COP (œstroprogestative)","color":"blue"},{"to":"q-micro-delai","label":"Pilule microprogestative (progestative seule)","color":"blue"}]},{"id":"q-cop-delai","kind":"decision","label":"Délai depuis l'oubli ? — Référence : la fenêtre de sécurité de la COP (se référer à la figure source pour le seuil horaire exact)","branches":[{"to":"q-cop-court-rapport","label":"Oubli récent (dans la fenêtre de tolérance)","color":"green"},{"to":"q-cop-long-rapport","label":"Oubli long (hors fenêtre de tolérance)","color":"amber"}]},{"id":"q-cop-court-rapport","kind":"decision","label":"Rapport sexuel dans les 5 jours précédant l'oubli ?","branches":[{"to":"t-cop-prendre-continuer","label":"Non","color":"green"},{"to":"t-cop-court-rapport-oui","label":"Oui","color":"amber"}]},{"id":"t-cop-prendre-continuer","kind":"terminal","label":"Prendre le comprimé oublié dès que possible — continuer normalement","color":"green","detail":"<h4>Conduite</h4><ul><li>Prendre le comprimé oublié <strong>immédiatement</strong> dès que possible</li><li>Poursuivre la <span class=\"kw-bio\">plaquette</span> à l'heure habituelle (même si double prise dans la journée)</li></ul><h4>Contraception d'<span class=\"kw-alerte\">urgence</span></h4><ul><li><strong>Non nécessaire</strong> — risque de <span class=\"kw-ci\">grossesse</span> négligeable dans ce contexte</li></ul>"},{"id":"t-cop-court-rapport-oui","kind":"terminal","label":"Prendre le comprimé oublié + préservatif 7 jours","color":"amber","detail":"<h4>Conduite</h4><ul><li>Prendre le comprimé oublié <strong>immédiatement</strong></li><li>Utiliser un <span class=\"kw-ttt\">préservatif</span> pendant les <span class=\"kw-chiffre\">7 jours</span> suivants</li><li>Rapport récent → évaluer la nécessité d'une <span class=\"kw-ttt\">contraception d'urgence</span> selon la position dans la <span class=\"kw-bio\">plaquette</span> (début <span class=\"kw-bio\">vs</span> fin)</li></ul><h4>Remarque</h4><ul><li><!-- ⚠️ KEVIN : vérifier sur la figure source si un rapport dans les 5 j précédents + oubli court nécessite systématiquement la CU, ou uniquement si début de plaquette --></li></ul>"},{"id":"q-cop-long-rapport","kind":"decision","label":"Rapport sexuel dans les 5 jours précédant l'oubli ?","branches":[{"to":"t-cop-long-sans-rapport","label":"Non","color":"amber"},{"to":"t-cop-long-avec-rapport","label":"Oui","color":"red"}]},{"id":"t-cop-long-sans-rapport","kind":"terminal","label":"Prendre le comprimé oublié + préservatif 7 jours","color":"amber","detail":"<h4>Conduite</h4><ul><li>Prendre le comprimé oublié <strong>dès que possible</strong></li><li>Utiliser un <span class=\"kw-ttt\">préservatif</span> pendant les <span class=\"kw-chiffre\">7 jours</span> suivants</li><li><span class=\"kw-ttt\">Contraception d'urgence</span> <strong>non requise</strong> ici (pas de rapport dans les 5 j)</li></ul><h4>Remarque</h4><ul><li><!-- ⚠️ KEVIN : confirmer sur la figure source si la position (début/fin plaquette) modifie cette conduite --></li></ul>"},{"id":"t-cop-long-avec-rapport","kind":"terminal","label":"Contraception d'urgence + préservatif 7 jours","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Contraception d'urgence</span> dès que possible :</li><li>→ <span class=\"kw-chiffre\">≤ 72h</span> : <span class=\"kw-ttt\">lévonorgestrel</span> (vente libre, gratuit)</li><li>→ <span class=\"kw-chiffre\">≤ 120h</span> : <span class=\"kw-ttt\">acétate d'ulipristal</span> ou <span class=\"kw-ttt\">DIU au cuivre</span> (<span class=\"kw-chiffre\">1ère intention</span>)</li><li>Prendre le comprimé oublié dès que possible</li><li>Utiliser un <span class=\"kw-ttt\">préservatif</span> pendant les <span class=\"kw-chiffre\">7 jours</span> suivants</li></ul><h4>Remarque</h4><ul><li><!-- ⚠️ KEVIN : la source renvoie à une figure pour les seuils horaires précis et la position dans la plaquette (début = risque ++ ; fin = risque moindre). Vérifier la figure image.png dans fiches sources/36/ --></li></ul>"},{"id":"q-micro-delai","kind":"decision","label":"Retard > fenêtre de tolérance ? — Lévonorgestrel : 3h · Désogestrel / drospirénone : 12h (source texte)","branches":[{"to":"t-micro-ok","label":"Non (retard dans la fenêtre)","color":"green"},{"to":"q-micro-rapport","label":"Oui (retard hors fenêtre)","color":"red"}]},{"id":"t-micro-ok","kind":"terminal","label":"Prendre le comprimé oublié — continuer normalement","color":"green","detail":"<h4>Conduite</h4><ul><li>Prendre le comprimé oublié <strong>immédiatement</strong></li><li>Continuer la <span class=\"kw-bio\">plaquette</span> à l'heure habituelle</li><li><span class=\"kw-chiffre\">Lévonorgestrel</span> : tolérance <span class=\"kw-chiffre\">3h</span> · <span class=\"kw-chiffre\">Désogestrel</span> : tolérance <span class=\"kw-chiffre\">12h</span> · <span class=\"kw-chiffre\">Drospirénone</span> : tolérance <span class=\"kw-chiffre\">24h</span></li></ul><h4>Contraception d'<span class=\"kw-alerte\">urgence</span></h4><ul><li><strong>Non nécessaire</strong></li></ul>"},{"id":"q-micro-rapport","kind":"decision","label":"Rapport sexuel dans les 5 jours précédant l'oubli ?","branches":[{"to":"t-micro-long-sans-rapport","label":"Non","color":"amber"},{"to":"t-micro-long-avec-rapport","label":"Oui","color":"red"}]},{"id":"t-micro-long-sans-rapport","kind":"terminal","label":"Prendre le comprimé oublié + préservatif ≥ 7 jours","color":"amber","detail":"<h4>Conduite</h4><ul><li>Prendre le comprimé oublié <strong>immédiatement</strong></li><li><span class=\"kw-ttt\">Contraception mécanique</span> (<span class=\"kw-ttt\">préservatif</span>) indispensable pendant <span class=\"kw-chiffre\">≥ 7 jours</span> (source texte)</li></ul><h4>Contraception d'<span class=\"kw-alerte\">urgence</span></h4><ul><li>Non requise ici (absence de rapport récent)</li></ul>"},{"id":"t-micro-long-avec-rapport","kind":"terminal","label":"Contraception d'urgence + préservatif ≥ 7 jours","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Contraception d'urgence</span> dès que possible :</li><li>→ <span class=\"kw-chiffre\">≤ 72h</span> : <span class=\"kw-ttt\">lévonorgestrel</span></li><li>→ <span class=\"kw-chiffre\">≤ 120h</span> : <span class=\"kw-ttt\">acétate d'ulipristal</span> ou <span class=\"kw-ttt\">DIU au cuivre</span></li><li><span class=\"kw-ttt\">Préservatif</span> pendant <span class=\"kw-chiffre\">≥ 7 jours</span></li></ul><h4>Remarque</h4><ul><li><!-- ⚠️ KEVIN : la source renvoie à la figure image.png pour le détail complet de la CAT selon le type de microprogestatif et la position dans la plaquette --></li></ul>"}]},"cards":[{"i":"02ffde462eb5","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Quels sont les trois grandes familles de méthodes contraceptives à connaître pour les EDN ?","a":"<ul><li>Les méthodes <strong>hormonales non définitives</strong>.</li><li>Les méthodes <strong>non hormonales non définitives</strong>.</li><li>Les méthodes <strong>définitives (stérilisation)</strong>.</li></ul>"},{"i":"0306f05dd02b","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Quelles sont les méthodes contraceptives définitives (stérilisation) et leur cadre juridique ?","a":"<ul><li>Chez la femme : <strong>ligature tubaire</strong> (souvent par cœlioscopie).</li><li>Chez l'homme : <strong>vasectomie bilatérale</strong>.</li><li>Ces méthodes sont encadrées par un texte juridique spécifiant que le/la patient·e doit être <strong>majeur·e</strong> et respecter un <strong>délai de réflexion de 4 mois</strong>.</li></ul>"},{"i":"2105259cae21","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Quelles sont les méthodes contraceptives hormonales non définitives ?","a":"<ul><li>Les méthodes hormonales <strong>combinées</strong> (œstrogène + progestatif) : pilule œstroprogestative (COP), patch transdermique, anneau vaginal.</li><li>Les méthodes <strong>progestatives seules</strong> : pilule microprogestative, implant sous-cutané, DIU au lévonorgestrel.</li></ul>"},{"i":"a86a5bb88af2","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Outre la prévention de la grossesse, quels sont les bénéfices additionnels de certaines méthodes contraceptives ?","a":"<ul><li>Le <strong>préservatif</strong> est la seule méthode qui protège des <strong>Infections Sexuellement Transmissibles (IST)</strong>.</li><li>Les <strong>contraceptions hormonales</strong> peuvent être prescrites pour des pathologies fonctionnelles ou organiques gynécologiques et mammaires, ou pour induire une <strong>aménorrhée thérapeutique</strong> (par exemple, en cas d'hémorragies liées à des troubles de l'hémostase ou à une endométriose).</li></ul>"},{"i":"eeb4e929d1fc","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Quelle est la définition de la contraception en médecine ?","a":"<p>La contraception désigne l'ensemble des méthodes visant à <strong>éviter, de façon réversible et pour une période donnée, la survenue d'une grossesse</strong>. Elle se distingue de la stérilisation qui est une méthode définitive.</p>"},{"i":"ff524c59e1cc","n":36,"o":"36-1","u":"Définition","t":"Connaître les différentes modalités de contraceptions existantes","q":"Quelles sont les méthodes contraceptives non hormonales non définitives ?","a":"<ul><li>Le <strong>DIU au cuivre</strong>.</li><li>Les <strong>méthodes barrières</strong> : préservatif masculin/féminin, spermicide, diaphragme, cape cervicale.</li><li>Les <strong>méthodes naturelles</strong> : Ogino-Knauss, méthode des températures, méthode de Billings, symptothermie (ces dernières n'étant pas suffisamment efficaces chez les femmes normalement fertiles).</li></ul>"},{"i":"0034031fc51a","n":36,"o":"36-10","u":"Suivi et/ou pronostic","t":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","q":"Quels sont les effets bénéfiques non contraceptifs des contraceptifs hormonaux combinés (COP) ?","a":"<p>Les effets bénéfiques non contraceptifs des COP incluent :</p><ul><li>Diminution du risque de certains cancers : <strong>cancer de l'ovaire</strong> (-30 à 50%), <strong>cancer de l'endomètre</strong> (-50%), <strong>cancer colorectal</strong>.</li><li>Amélioration des symptômes gynécologiques : diminution des <strong>dysménorrhées</strong>, des <strong>ménorragies fonctionnelles</strong>, du <strong>syndrome prémenstruel</strong>, et de l'<strong>acné</strong>.</li></ul>"},{"i":"43b2af4a1aea","n":36,"o":"36-10","u":"Suivi et/ou pronostic","t":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","q":"Quel est le profil de tolérance et les effets indésirables spécifiques des microprogestatifs ?","a":"<p>Les microprogestatifs présentent un avantage majeur : l'<strong>absence d'effets métaboliques et vasculaires</strong>, permettant leur prescription chez les femmes à risque vasculaire.</p><p>Leurs effets indésirables incluent :</p><ul><li>Un <strong>retour de couches hémorragique</strong> en post-partum (par atrophie de l'endomètre).</li><li>Une augmentation du risque de <strong>grossesse extra-utérine (GEU)</strong>.</li><li>Des <strong>troubles du cycle</strong>, des <strong>spottings</strong> et une <strong>aménorrhée</strong> (fréquents).</li><li>Des <strong>dystrophies ovariennes</strong> pouvant entraîner un climat d'hyperœstrogénie relative, se manifestant par un syndrome prémenstruel, des kystes fonctionnels et des signes d'hyperandrogénie (acné, hirsutisme).</li></ul>"},{"i":"7b614e758a98","n":36,"o":"36-10","u":"Suivi et/ou pronostic","t":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","q":"Quels sont les principaux facteurs de risque qui augmentent le risque artériel sous contraceptifs hormonaux combinés ?","a":"<p>Les principaux facteurs de risque qui augmentent le risque artériel sous COP sont :</p><ul><li>Âge <strong>> 35 ans</strong>.</li><li><strong>Antécédents familiaux de 1<sup>er</sup> degré</strong> de maladie artérielle jeune (&lt; 60 ans).</li><li><strong>Obésité / surpoids</strong>.</li><li><strong>Tabac</strong> (effet dose-dépendant).</li><li><strong>Migraine avec aura</strong>, qui majore significativement le risque d'AVC ischémique.</li></ul>"},{"i":"8b67efaf223c","n":36,"o":"36-10","u":"Suivi et/ou pronostic","t":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","q":"Quels sont les effets indésirables spécifiques et les complications graves des dispositifs intra-utérins (DIU), qu'ils soient au cuivre ou au lévonorgestrel ?","a":"<p>Les effets indésirables spécifiques et les complications graves des DIU sont :</p><ul><li><strong>DIU au cuivre</strong> : <strong>ménorragies</strong> et <strong>dysménorrhées</strong>.</li><li><strong>DIU au lévonorgestrel</strong> : <strong>aménorrhée</strong> (30-50%), <strong>métrorragies</strong> (10-15%), syndrome prémenstruel, kystes ovariens fonctionnels et signes d'hyperandrogénie modérée (séborrhée, acné, hirsutisme).</li><li><strong>Complications graves (tout DIU)</strong> : <strong>infection génitale</strong>, <strong>expulsion spontanée</strong>, et <strong>perforation utérine</strong> (souvent liée à une pose douloureuse). Ces dernières constituent une urgence.</li></ul>"},{"i":"95625c2ae036","n":36,"o":"36-10","u":"Suivi et/ou pronostic","t":"Connaître la tolérance et les effets indésirables des différents contraceptifs hormonaux","q":"Quels sont les principaux risques cardiovasculaires associés aux contraceptifs hormonaux combinés (COP) ?","a":"<p>Les risques cardiovasculaires des COP sont :</p><ul><li><strong>Risque thromboembolique veineux (MTEV)</strong> : multiplié par <strong>3</strong>, présent avec toutes les COP. Le risque est le plus faible avec la <strong>2<sup>e</sup> génération (lévonorgestrel)</strong>, et le plus élevé avec la 3<sup>e</sup> génération (autres que norgestimate), la drospirénone et l'acétate de cyprotérone. Le patch et l'anneau ont un risque équivalent à la 3<sup>e</sup> génération.</li><li><strong>Risque artériel (IDM, AVC)</strong> : surtout chez les femmes à risque, par action synergique sur le métabolisme glucidique (insulinorésistance), lipidique (augmentation des TG, CT, HDL) et sur l'hypertension artérielle (environ <strong>5%</strong> des femmes).</li></ul>"},{"i":"1b1b6f6b0a3c","n":36,"o":"36-13","u":"Suivi et/ou pronostic","t":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","q":"Comment l'efficacité d'une méthode contraceptive est-elle définie et mesurée en France ?","a":"<p>L'efficacité d'une méthode contraceptive est mesurée par l'<strong>indice de Pearl</strong>. C'est le nombre de grossesses accidentelles pour <strong>100 femmes</strong> après <strong>12 mois</strong> d'utilisation. Plus cet indice est faible, plus la méthode est efficace.</p>"},{"i":"68a903c03d40","n":36,"o":"36-13","u":"Suivi et/ou pronostic","t":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","q":"Quels sont les niveaux d'efficacité et délais d'utilisation des contraceptions d'urgence médicamenteuses ?","a":"<ul><li>L'<strong>acétate d'ulipristal</strong> (EllaOne®) est plus efficace que le lévonorgestrel et peut être utilisé jusqu'à <strong>120 heures</strong> après le rapport non protégé.</li><li>Le <strong>lévonorgestrel</strong> (NorLevo®) est d'autant plus efficace qu'il est pris précocement, et peut être utilisé jusqu'à <strong>72 heures</strong> après le rapport non protégé.</li></ul>"},{"i":"7aee825a47d7","n":36,"o":"36-13","u":"Suivi et/ou pronostic","t":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","q":"Quelles sont les méthodes contraceptives permanentes ou de longue durée, les plus efficaces, et quels sont leurs indices de Pearl en utilisation courante ?","a":"<ul><li>L'<strong>implant au lévonorgestrel</strong> a un taux de grossesse de <strong>0,05%</strong>.</li><li>Le <strong>DIU au lévonorgestrel</strong> (stérilet hormonal) a un taux de grossesse de <strong>0,1%</strong>.</li><li>La <strong>stérilisation féminine</strong> a un taux de grossesse de <strong>0,5%</strong>.</li><li>La <strong>stérilisation masculine</strong> (vasectomie) a un taux de grossesse de <strong>0,15%</strong>.</li></ul>"},{"i":"941ed3a908f8","n":36,"o":"36-13","u":"Suivi et/ou pronostic","t":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","q":"Quelle est la méthode de contraception d'urgence la plus efficace et combien de temps après le rapport peut-elle être utilisée ?","a":"<p>Le <strong>DIU au cuivre</strong> est la méthode de contraception d'urgence la plus efficace, avec une efficacité d'environ <strong>99%</strong>. Il peut être inséré jusqu'à <strong>120 heures</strong> (5 jours) après le rapport non protégé.</p>"},{"i":"db6a4526121d","n":36,"o":"36-13","u":"Suivi et/ou pronostic","t":"Connaître les niveaux d’efficacité des différentes stratégies contraceptives et des contraceptions d’urgence (indice de Pearl)","q":"Quels sont les niveaux d'efficacité des principales méthodes contraceptives hormonales combinées et microprogestatives en utilisation courante et parfaite ?","a":"<ul><li>Les <strong>pilules combinées œstroprogestatives</strong> (orale, patch, anneau) ont un taux de grossesse de <strong>8%</strong> en utilisation courante et <strong>0,3%</strong> en utilisation parfaite.</li><li>Les <strong>pilules microprogestatives</strong> ont un taux de grossesse de <strong>8%</strong> en utilisation courante et <strong>0,3%</strong> en utilisation parfaite.</li></ul>"},{"i":"a0549d45a06c","n":36,"o":"36-16","u":"Suivi et/ou pronostic","t":"Connaître les interactions potentielles médicamenteuses","q":"Existe-t-il des interactions entre les antibiotiques à large spectre et la contraception hormonale ?","a":"<p>Hors rifampicine et rifabutine (qui sont des inducteurs enzymatiques), il n'y a <strong>pas d'interaction démontrée</strong> entre les antibiotiques à large spectre et la contraception hormonale. Cependant, en pratique courante, il est souvent conseillé d'utiliser un <strong>préservatif additionnel</strong> pendant la cure et les <strong>7 jours suivant l'arrêt</strong> de l'antibiotique par précaution.</p>"},{"i":"e2967aeb4527","n":36,"o":"36-16","u":"Suivi et/ou pronostic","t":"Connaître les interactions potentielles médicamenteuses","q":"Comment les inducteurs enzymatiques interagissent-ils avec la contraception hormonale et quelles en sont les conséquences cliniques ?","a":"<p>Les inducteurs enzymatiques <strong>accélèrent le métabolisme hépatique des stéroïdes contraceptifs</strong>. Cela entraîne une <strong>diminution de l'efficacité contraceptive</strong> et un risque accru de grossesse non désirée.</p>"},{"i":"e5a957f1b913","n":36,"o":"36-16","u":"Suivi et/ou pronostic","t":"Connaître les interactions potentielles médicamenteuses","q":"Quels sont les principaux inducteurs enzymatiques interagissant avec la contraception hormonale, et quelle est la conduite à tenir face à cette interaction ?","a":"<p>Les principaux inducteurs enzymatiques peuvent être mémorisés par le moyen mnémotechnique PRECaMPaGNe :</p><ul><li><strong>P</strong>hénytoïne</li><li><strong>R</strong>ifampicine / Rifabutine</li><li><strong>E</strong>favirenz / <strong>Ca</strong>rbamazépine</li><li><strong>M</strong>odafinil</li><li><strong>Pa</strong>rphénobarbital</li><li><strong>G</strong>riséofulvine</li><li><strong>Ne</strong>virapine</li></ul><p>D'autres incluent le millepertuis, le topiramate et certains antiprotéases du VIH.</p><p>La conduite à tenir consiste à utiliser une <strong>contraception mécanique associée</strong> (préservatifs) ou à changer pour une <strong>méthode contraceptive non hormonale</strong> (exemple : DIU au cuivre).</p>"},{"i":"f3a295393dd0","n":36,"o":"36-16","u":"Suivi et/ou pronostic","t":"Connaître les interactions potentielles médicamenteuses","q":"Quel est le mécanisme d'interaction des contraceptifs oraux avec la lamotrigine, et quelle en est la prise en charge ?","a":"<p>Les contraceptifs oraux (COP) <strong>accélèrent le métabolisme de la lamotrigine</strong>, ce qui entraîne une <strong>diminution de sa concentration plasmatique</strong>. Cette baisse peut provoquer une <strong>recrudescence des crises d'épilepsie</strong> chez la patiente.</p><p>En cas d'association nécessaire, une <strong>surveillance clinique rapprochée</strong> est indispensable, avec une <strong>adaptation posologique</strong> de la lamotrigine. L'association reste possible sous réserve de cette surveillance.</p>"},{"i":"364f4cd86b06","n":36,"o":"36-20","u":"Définition","t":"Connaître les différents modes de stérilisation féminine et masculine et l’existence d’une législation","q":"Quelle est la méthode de stérilisation masculine, et quelles sont les précautions à prendre pour en assurer l'efficacité ?","a":"<p>La stérilisation masculine est la <strong>vasectomie bilatérale</strong>, consistant en la <strong>section d'une portion des deux canaux déférents</strong>, sous anesthésie locale, locorégionale ou générale. L'efficacité n'est <strong>pas immédiate</strong> : une autre contraception doit être maintenue pendant <strong>12 semaines</strong> (soit 90 jours) et plus de 30 éjaculations. Un <strong>spermogramme de contrôle</strong> est indispensable pour vérifier l'efficacité (<strong>azoospermie</strong> ou <strong>&lt; 100 000 spz/ml non mobiles</strong>) avant d'arrêter l'autre contraception. La <strong>cryoconservation du sperme au CECOS</strong> peut être proposée avant le geste.</p>"},{"i":"44dccd464931","n":36,"o":"36-20","u":"Définition","t":"Connaître les différents modes de stérilisation féminine et masculine et l’existence d’une législation","q":"Quel est le parcours législatif obligatoire pour une stérilisation à visée contraceptive, autant pour les hommes que pour les femmes ?","a":"<ul><li>Une <strong>première consultation</strong> donne lieu à une demande motivée, la remise d'un dossier d'information écrit et d'une attestation de consultation.</li><li>Un <strong>délai de réflexion obligatoire de 4 mois</strong> doit être respecté.</li><li>Une <strong>deuxième consultation</strong> permet la confirmation écrite du consentement éclairé du patient.</li><li>L'acte doit se dérouler dans un <strong>établissement de santé</strong> (hôpital ou clinique).</li></ul>"},{"i":"8e4adfcd7685","n":36,"o":"36-20","u":"Définition","t":"Connaître les différents modes de stérilisation féminine et masculine et l’existence d’une législation","q":"Comment est encadrée légalement la stérilisation à visée contraceptive en France ?","a":"<p>La stérilisation à visée contraceptive est encadrée par des textes juridiques stricts qui garantissent le caractère éclairé du consentement. Elle est réservée aux <strong>adultes majeurs</strong>. Si la personne est sous tutelle ou curatelle, la décision est soumise au <strong>juge des tutelles</strong> après audition du représentant légal.</p>"},{"i":"f54cda38e4a2","n":36,"o":"36-20","u":"Définition","t":"Connaître les différents modes de stérilisation féminine et masculine et l’existence d’une législation","q":"Quelles sont les méthodes chirurgicales de stérilisation féminine actuellement pratiquées en France et leurs caractéristiques principales ?","a":"<p>Actuellement, la seule méthode chirurgicale de stérilisation féminine pratiquée en France est la <strong>méthode cœlioscopique</strong>, réalisée sous <strong>anesthésie générale</strong>. Elle consiste en la <strong>pose de clips ou d'anneaux tubaires</strong>, ou une <strong>section-ligature des trompes</strong>, avec une efficacité <strong>immédiate</strong>. La méthode hystéroscopique (dispositif Essure®) n'est plus disponible en France depuis 2017.</p>"},{"i":"350b8fc8fc57","n":36,"o":"36-3","u":"Définition","t":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","q":"Quelles sont les voies d'administration des contraceptions hormonales microprogestatives disponibles en France ?","a":"<ul><li><strong>Orale</strong></li><li><strong>Sous-cutanée</strong> (implant)</li><li><strong>Intra-utérine</strong> (DIU)</li></ul>"},{"i":"a2b66a608a30","n":36,"o":"36-3","u":"Définition","t":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","q":"Qu'est-ce qu'une contraception hormonale progestative seule ?","a":"<p>La contraception progestative seule repose sur l'administration continue de <strong>petites doses de progestatif</strong> (microprogestatifs).</p>"},{"i":"caa69675f522","n":36,"o":"36-3","u":"Définition","t":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","q":"Citez les DCI des microprogestatifs oraux et leurs spécificités de prise.","a":"<ul><li><strong>Lévonorgestrel</strong> (Microval®) : retard maximum autorisé de <strong>3 heures</strong>.</li><li><strong>Désogestrel</strong> (Cérazette®, Antigone®, Desopop®, Optimizette®) : retard maximum autorisé de <strong>12 heures</strong>.</li><li><strong>Drospirénone</strong> (Slinda®) : retard maximum autorisé de <strong>24 heures</strong> (comprimés 24 actifs + 4 placebo).</li></ul><p>Après le délai autorisé, une contraception mécanique complémentaire est indispensable pendant au moins <strong>une semaine</strong>.</p>"},{"i":"db2e31cadc26","n":36,"o":"36-3","u":"Définition","t":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","q":"Quelles sont les caractéristiques de l'implant sous-cutané progestatif ?","a":"<p>Il contient de l'<strong>étonogestrel</strong> (Nexplanon®) et délivre 25-70 µg/24h. Il est posé à la face interne du bras non dominant après anesthésie locale. Sa durée d'efficacité est de <strong>3 ans</strong> et son observance est parfaite.</p>"},{"i":"f1091564ca83","n":36,"o":"36-3","u":"Définition","t":"Connaître les différents types de contraceptions hormonales pro-gestatives, leurs voies d’administration","q":"Quelles sont les caractéristiques des DIU au lévonorgestrel et leurs indications principales ?","a":"<ul><li>Différents dosages existent : Mirena® (52 mg/20 µg/24h), Kyleena® (19,5 mg/9 µg/24h), Jaydess® (13,5 mg/6 µg/24h).</li><li>Ils agissent par atrophie de l'endomètre, épaississement de la glaire cervicale et toxicité sur les spermatozoïdes.</li><li>Leur durée d'efficacité est de <strong>5 ans</strong> pour Mirena® et Kyleena®, et <strong>3 ans</strong> pour Jaydess®.</li><li>Ils sont particulièrement indiqués en cas de <strong>dysménorrhée</strong>, <strong>ménorragies fonctionnelles</strong> ou <strong>adénomyose</strong>.</li></ul>"},{"i":"31671da59ec2","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Quelle est la particularité principale du DIU au cuivre en tant que contraception d'urgence ?","a":"<p>Le DIU au cuivre est la <strong>première intention en termes d'efficacité</strong> parmi les méthodes de contraception d'urgence. Il a en outre l'avantage de fournir une <strong>contraception à longue durée d'action</strong>. Cependant, il est plus rarement mis en œuvre en pratique pour la contraception d'urgence par rapport aux pilules.</p>"},{"i":"4f752fcb02d2","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Qu'est-ce que la contraception d'urgence (CU) ?","a":"<p>La contraception d'urgence (CU) est une <strong>méthode d'exception</strong> utilisée après un rapport sexuel non protégé ou un échec de contraception habituelle (ex. : oubli de pilule, rupture de préservatif).</p>"},{"i":"604efc1bcdf4","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Quelle est l'efficacité et les particularités d'accès à la contraception d'urgence par lévonorgestrel ?","a":"<p>Le lévonorgestrel est efficace jusqu'à <strong>72 heures</strong> après le rapport, d'autant plus que la prise est précoce. Il est en <strong>vente libre, sans ordonnance</strong>, et est gratuit pour les mineures et majeures. Il est accessible en pharmacie, planning familial ou lycée, et n'a aucune contre-indication connue.</p>"},{"i":"6afb49da9044","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Quels sont les différents types de contraception d'urgence disponibles et leurs délais d'efficacité respectifs ?","a":"<ul><li>Le <strong>lévonorgestrel</strong> (Norlevo®) : efficace jusqu'à <strong>72 heures</strong> (3 jours) après le rapport.</li><li>L'<strong>acétate d'ulipristal</strong> (EllaOne®) : efficace jusqu'à <strong>120 heures</strong> (5 jours) après le rapport.</li><li>Le <strong>Dispositif Intra-Utérin (DIU) au cuivre</strong> : efficace jusqu'à <strong>120 heures</strong> (5 jours) après le rapport.</li></ul>"},{"i":"b9dbca83614e","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Quelle est l'efficacité et les particularités d'accès à la contraception d'urgence par acétate d'ulipristal ?","a":"<p>L'acétate d'ulipristal est efficace jusqu'à <strong>120 heures</strong> après le rapport et est considéré comme plus efficace que le lévonorgestrel. Il est disponible en pharmacie avec ou sans ordonnance, et en planning familial. Il est remboursé à 65% sur ordonnance. Les contre-indications incluent l'<strong>asthme sévère</strong> et l'<strong>insuffisance hépatique</strong>.</p>"},{"i":"d6ee03ec2100","n":36,"o":"36-4","u":"Définition","t":"Connaître les différents types de contraception d’urgence","q":"Quel est le mécanisme d'action principal des pilules de contraception d'urgence (lévonorgestrel et acétate d'ulipristal) et celui du DIU au cuivre ?","a":"<ul><li>Les <strong>pilules de contraception d'urgence</strong> (lévonorgestrel et acétate d'ulipristal) visent principalement à <strong>inhiber ou retarder l'ovulation</strong>. Le lévonorgestrel interfère avec le pic de LH, tandis que l'acétate d'ulipristal, modulateur sélectif des récepteurs à la progestérone, inhibe la croissance folliculaire et retarde le pic de LH.</li><li>Le <strong>DIU au cuivre</strong> agit par sa toxicité directe du cuivre sur les gamètes et par une action inflammatoire endométriale rendant l'endomètre impropre à la nidation.</li></ul>"},{"i":"0de94b5cfa36","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Quelle méthode contraceptive barrière est la seule à protéger des Infections Sexuellement Transmissibles (IST) ?","a":"<p>Le <stong>préservatif masculin</stong> est la seule méthode contraceptive barrière qui protège des IST.</p>"},{"i":"16fb50cdb557","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Quelles sont les principales méthodes contraceptives naturelles et comment fonctionnent-elles ?","a":"<ul><li><strong>Méthode Ogino-Knauss</strong> : Abstinence pendant la <stong>période fertile estimée</stong> du cycle.</li><li><strong>Courbes de températures</strong> : Repérage de l'<stong>ovulation par décalage thermique</stong>.</li><li><strong>Méthode Billings</strong> : Observation de la <stong>glaire cervicale</stong>.</li><li><strong>Symptothermie</strong> : Combinaison de la <stong>température et de l'observation de la glaire</stong>.</li><li><strong>Retrait (coït interrompu)</strong> : Indice de Pearl de <stong>27 %</stong> (usage courant).</li></ul>"},{"i":"32f1d3530936","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Quels sont les principes et les efficacités usuelles des principales méthodes contraceptives barrières comme le préservatif masculin, le préservatif féminin et le diaphragme ?","a":"<ul><li><strong>Préservatif masculin</strong> : Barrière mécanique en latex/polyuréthane sur le pénis. Indice de Pearl : <stong>15 %</stong> (usage courant).</li><li><strong>Préservatif féminin</strong> : Gaine en polyuréthane insérée dans le vagin. Indice de Pearl : <stong>21 %</stong> (usage courant).</li><li><strong>Diaphragme</strong> : Dôme en silicone obturant le col, associé à un spermicide. Indice de Pearl : <stong>16 %</stong> (usage courant).</li></ul>"},{"i":"38f47899432a","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Pourquoi les spermicides seuls ne sont-ils pas recommandés comme contraception principale et comment doivent-ils être utilisés ?","a":"<p>Les spermicides ont une <stong>faible efficacité seuls</stong> (Indice de Pearl de <stong>29 %</stong> en usage courant). Ils doivent être <stong>associés à une autre méthode</stong> contraceptive pour être efficaces.</p>"},{"i":"8db694aa3883","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Dans quelles conditions les méthodes de contraception naturelles sont-elles jugées efficaces et peuvent-elles être proposées comme méthode unique ?","a":"<p>Les méthodes naturelles sont <stong>non suffisamment efficaces chez les femmes normalement fertiles</stong>. Elles ne doivent <stong>jamais être proposées comme méthode unique</stong> chez une femme en âge de procréer souhaitant éviter une grossesse, <stong>sauf situations particulières</stong> comme le MAMA (Méthode de l'Allaitement Maternelle et de l'Aménorrhée) pendant l'allaitement.</p>"},{"i":"a40450a7612f","n":36,"o":"36-6","u":"Définition","t":"Connaître les contraceptions barrières (et notamment le préservatif masculin) et naturelles","q":"Comment les méthodes contraceptives barrières et naturelles se positionnent-elles en termes d'efficacité par rapport aux autres méthodes contraceptives ?","a":"<p>Les méthodes contraceptives barrières et naturelles sont <stong>d'efficacité inférieure</stong> aux méthodes hormonales et au DIU.</p>"},{"i":"523982ec2890","n":36,"o":"36-7","u":"Prise en charge","t":"Connaître les contre-indications de la contraception estroprogestative, progestative, intra-utérine","q":"Quelles sont les contre-indications artérielles absolues à la contraception estroprogestative (COP) ?","a":"<p>Les contre-indications artérielles absolues à la COP sont :</p><ul><li>Les <strong>antécédents personnels ou familiaux au 1er degré avant 50 ans</strong> d'infarctus du myocarde (IDM), d'accident vasculaire cérébral (AVC) ischémique ou d'artériopathie oblitérante des membres inférieurs (AOMI).</li><li>Un <strong>tabagisme important</strong>.</li><li>Une <strong>hypertension artérielle</strong> (même traitée et équilibrée).</li><li>Une <strong>migraine avec aura</strong>.</li><li>Un <strong>diabète de type 1 compliqué</strong> ou d'une durée supérieure à <strong>20 ans</strong>.</li><li>Une <strong>dyslipidémie non équilibrée et/ou non traitée</strong>.</li></ul>"},{"i":"5390f43c0ce2","n":36,"o":"36-7","u":"Prise en charge","t":"Connaître les contre-indications de la contraception estroprogestative, progestative, intra-utérine","q":"Quelles sont les contre-indications formelles aux microprogestatifs ?","a":"<p>Les contre-indications formelles aux microprogestatifs sont :</p><ul><li>Les <strong>accidents thromboemboliques veineux évolutifs</strong>.</li><li>Les <strong>pathologies hépatiques évolutives sévères</strong>.</li><li>Le <strong>cancer du sein</strong> (y compris non hormonodépendant) et le <strong>cancer de l'endomètre</strong>.</li><li>Les <strong>pathologies hormonodépendantes vis-à-vis de la progestérone</strong> (par exemple, un méningiome).</li><li>Les <strong>saignements inexpliqués</strong>.</li></ul>"},{"i":"541d48ff0bd8","n":36,"o":"36-7","u":"Prise en charge","t":"Connaître les contre-indications de la contraception estroprogestative, progestative, intra-utérine","q":"Quelles sont les contre-indications générales à la pose de tout dispositif intra-utérin (DIU) ?","a":"<p>Les contre-indications générales à la pose de tout DIU sont :</p><ul><li>Une <strong>grossesse en cours et désirée</strong>.</li><li>Les <strong>anomalies de la cavité utérine</strong> (malformations, myomes utérins).</li><li>Les <strong>valvulopathies à risque d'endocardite</strong>.</li><li>Une <strong>maladie trophoblastique gestationnelle maligne</strong>.</li><li>Les <strong>hémorragies génitales non diagnostiquées</strong>.</li><li>Les <strong>contre-indications infectieuses</strong> telles qu'une infection puerpérale en cours, un antécédent d'infection génitale haute de moins de 3 mois, une cervicite purulente, un état juste après un avortement septique, ou une tuberculose pelvienne avérée.</li></ul>"},{"i":"bd062e8257be","n":36,"o":"36-7","u":"Prise en charge","t":"Connaître les contre-indications de la contraception estroprogestative, progestative, intra-utérine","q":"Quelles sont les contre-indications carcinologiques à la contraception estroprogestative (COP) ?","a":"<p>Les contre-indications carcinologiques à la COP sont :</p><ul><li>Une <strong>tumeur maligne du sein</strong> (même non hormonodépendante).</li><li>Une <strong>tumeur maligne de l'utérus</strong> (endomètre), même si la COP diminue le risque de cancer de l'endomètre.</li></ul>"}]};